export const records = [{"schema_version":1,"id":"AUT-0461","slug":"sales-commission-reversal-after-return-credit-memo","title":"Перерахунок комісії продавця після повернення чи скасування продажу","summary":"Повернення, кредит-ноту або скасування продажу пов’язують із початковою комісією та перераховують її за затвердженим планом винагороди.","problem":"Продаж уже нарахував комісію, але пізніше клієнту повернули частину суми або кредитували рахунок. Без зв’язку з первинною комісією компанія може повторно нарахувати винагороду, зменшити її не за тим правилом або безпідставно утримати суму з уже виплаченої зарплати.","outcome":"Кожна зміна продажу має перевірений зв’язок із первинною комісією, сумою перерахунку, правилом плану й затвердженим обліковим результатом.","category":"finance","subcategory":"payments","roles":["finance-specialist","sales-manager","operations-manager"],"industries":["wholesale","retail","professional-services"],"triggers":["Після нарахування комісії в обліку проведено повернення, часткове скасування продажу або кредит-ноту."],"workflow_steps":["Отримати проведену подію повернення чи кредитування з ідентифікаторами клієнта, документа, рядка продажу, суми й дати.","Зіставити її з первинним замовленням, рахунком та рядками комісії; неповний або неоднозначний зв’язок передати на ручну звірку.","Визначити початковий план винагороди, правило нарахування, продавця, період і статус виплати на дату первинного продажу.","Перерахувати тільки частину комісії, на яку впливає проведена подія; часткове повернення не скасовує всю комісію автоматично.","Перевірити попередні коригування за унікальним ID події, щоб повторна доставка повідомлення не створила друге списання.","Показати джерельні документи, початкове нарахування, від’ємну або іншу коригувальну суму та правило розрахунку менеджеру й фінансисту.","Після затвердження передати коригування в систему комісій або розрахунку винагород і повторно прочитати збережений результат.","Якщо первинна комісія вже виплачена, створити окремий випадок для погодженого майбутнього розрахунку; не утримувати гроші із зарплати без перевіреної політики та правової підстави."],"requirements":["Збережено стабільні посилання між поверненням або кредит-нотою, первинним продажем і розрахованою комісією.","План винагороди визначає обробку часткових повернень, дати чинності правил і коригувань після виплати.","Відомо, хто погоджує суму та як передати коригування до системи комісій або payroll."],"limitations":["Різні плани визначають момент і суму зміни комісії по-різному; приклади Oracle та NetSuite не є правилом для кожного клієнта.","Кредит-нота не завжди означає фактичне повернення грошей клієнту; умови виплати комісії потрібно перевіряти окремо.","Картка не визначає законність відрахувань із заробітної плати. Такі дії потребують окремої перевірки політики й місцевих вимог.","Години попередні; якість зіставлення даних, кількість планів винагород і статус попередніх виплат уточнюють під час аудиту."],"problems":["як перерахувати комісію менеджера якщо клієнту повернули гроші за замовлення","як не платити комісію вдруге за скасований продаж","кредит нота після нарахування комісії продавцю"],"synonyms":["commission reversal","sales commission clawback","credit memo commission adjustment","коригування комісії за повернення"],"search_queries":["як звірити кредит-ноту з раніше нарахованою комісією продавця","як перерахувати часткове повернення в плані продажних винагород"],"sources":[{"type":"vendor_documentation","title":"NetSuite: Commission and Credit Memos","url":"https://docs.oracle.com/en/cloud/saas/netsuite/ns-online-help/section_3720939620.html","checked_at":"2026-10-09","supports":"Описує від’ємну комісію за кредит-нотою та різну поведінку clawback залежно від плану: billing-based чи cash-collection-based і повернення грошей клієнту."},{"type":"vendor_documentation","title":"Oracle Incentive Compensation User Guide: Receivables events and order adjustments","url":"https://docs.oracle.com/cd/E26401_01/doc.122/e49154/T300492T300502.htm","checked_at":"2026-10-09","supports":"Документує кредит-ноти й повернення як події розрахунку винагород; змінений рядок продажу може створити від’ємну реверсну транзакцію для вже завантаженої комісії."},{"type":"vendor_documentation","title":"Oracle Order Management: Manage Channel Programs on Sales Orders","url":"https://docs.oracle.com/en/cloud/saas/supply-chain-and-manufacturing/26a/fauom/manage-channel-programs-on-sales-orders.html","checked_at":"2026-10-09","supports":"Підтверджує, що при поверненні з посиланням на початковий рядок система копіює й реверсує його incentive; не описує комісію продавця."},{"type":"inferred_pattern","title":"Редакційний процес контрольованого перерахунку комісії","supports":"Ідемпотентність, ручне погодження та межі інтеграції є проєктними вимогами картки; години не підтверджені клієнтським впровадженням."}],"status":"draft","variants":[{"id":"commission-return-review-tracked","title":"Ручна перевірка коригування комісії","description":"Фінансист перевіряє джерельні документи, формулу плану й статус виплати та передає погоджене коригування відповідальному фахівцю.","best_for":["Компаній із небагатьма поверненнями та розрахунком комісії у таблиці або системі без потрібного API."],"example":"За продаж із комісією 500 USD провели кредит-ноту на 20% вартості. За правилом плану фінансист розрахував коригування 100 USD, звірив попередню виплату й передав його на погодження.","implementation_methods":["Пов’язати документ повернення з продажем і рядком розрахунку комісії.","Зберігати тип події, формулу, суму та погодження окремим записом.","Після внесення коригування звірити його з реєстром комісій."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Доступні документи повернення, первинний продаж і чинний план винагороди."],"limitations":["Масове зіставлення та автоматична передача коригувань не входять до варіанта."],"pricing_modifiers":[]},{"id":"commission-return-integrated","title":"Подієве зіставлення та передача коригування","description":"Перевірений інтеграційний процес знаходить первинну комісію за ID повернення, обчислює дозволений вплив і передає винятки на погодження.","best_for":["Системи комісій і продажів мають API або надійний експорт з незмінними ID подій."],"example":"Система отримала кредит-ноту 200 USD, знайшла рядок продажу й продавця, застосувала правило чинного плану, створила коригування комісії та не повторила його після повторної доставки події.","implementation_methods":["Читати проведені повернення, кредит-ноти, рядки продажу, продавця та збережені комісії.","Версіонувати таблицю правил із датами чинності й обмежувати суму первинною комісією.","Записувати коригування після погодження, перечитувати результат і зберігати ID транзакції."],"complexity":"high","hours_min":48,"hours_max":96,"requirements":["Підтверджені API або стабільний експорт, документація планів комісії та тестовий контур."],"limitations":["Утримання вже виплаченої комісії не автоматизується без окремо затвердженої політики й перевірки права."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0058","reason":"Картка повернень керує товаром і рішенням про обмін. Ця картка перераховує комісію за проведеним фінансовим коригуванням продажу."},{"type":"related","target_id":"AUT-0200","reason":"Картка повернення коштів контролює погоджене відшкодування клієнту; ця картка змінює винагороду продавця за правилами комісійного плану."},{"type":"related","target_id":"AUT-0404","reason":"Розподіл комісії платежу визначає одержувачів комісійних зборів за транзакцією. Ця картка коригує sales commission через подальше повернення або credit memo."}],"configurator_questions":[{"id":"commission-return-multiple-credit-lines","question":"Чи потрібно коригувати комісію кільком продавцям або сплітам одного продажу?","help_text":"Вкажіть правило розподілу початкової комісії та власника кожної частини.","type":"boolean","required":true,"options":[],"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додається пошук усіх одержувачів і збереження розподілу первинної комісії."}]},{"id":"commission-return-already-paid","question":"Чи можуть повернення стосуватися комісії, яку вже виплатили?","help_text":"Потрібні погоджені правила обліку відповідальності й спосіб коригування майбутньої винагороди.","type":"boolean","required":true,"options":[],"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Додається окремий маршрут залишку без автоматичного payroll-відрахування."}]}]},{"schema_version":1,"id":"AUT-0462","slug":"employee-role-change-access-transition-review","title":"Перегляд доступів після зміни посади або відділу","summary":"Зміна ролі працівника запускає перевірку старих і потрібних нових доступів із погодженим переходом та підтвердженням результату.","problem":"Працівника переводять до іншого відділу або змінюють його посаду. Нові права додають за запитом менеджера, але старі доступи часто залишаються активними, а власники систем не бачать повної зміни ролі.","outcome":"Для кожної кадрової зміни визначені старі права, схвалені нові права, дата переходу, власники систем і перевірений результат відкликання та надання доступів.","category":"hr","subcategory":"workforce","roles":["hr-specialist","operations-manager","owner"],"industries":["professional-services","manufacturing","retail"],"triggers":["У кадровому джерелі змінилася посада, відділ або керівник працівника."],"workflow_steps":["Отримати підтверджену кадрову подію з ідентифікатором працівника, старою та новою посадою, підрозділом, керівником і датою чинності.","Перевірити попередній і новий профілі доступу за каталогом ролей; невідомі або надмірно широкі призначення передати власнику ресурсу.","Скласти перелік прав до відкликання, нових прав на погодження та дозволених тимчасових винятків для передавання роботи.","Надіслати рішення керівнику й власникам відповідних систем; несумісні ролі або конфлікти обов’язків ескалювати окремому погоджувачу.","Запланувати зміну на дату переходу: старі права відкликати у погоджений строк, нові надати після потрібних погоджень.","Для перехідного доступу встановити власника й дату автоматичного завершення; відсутність відповіді не продовжує права.","Передати затверджені зміни до перевірених систем або виконавцям, зберігаючи окремий статус для кожного застосунку й групи.","Повторно прочитати поточні призначення, порівняти їх із погодженим набором і залишити невиконані відкликання відкритими винятками.","Зберегти кадрову подію, версію профілю, рішення погоджувачів, виконавців, часові мітки й результат для аудиту."],"requirements":["Кадрове джерело передає достовірні зміни ролі та дату набрання ними чинності.","Є погоджений каталог профілів доступу, власників систем і матриця несумісних повноважень.","Визначені правила строків відкликання, тимчасового доступу, винятків і підтвердження фактичного стану систем."],"limitations":["Кадрова зміна не доводить, що нові права вже погоджені або що всі системи підтримують автоматичне відкликання.","Профілі доступу, матрицю несумісних обов’язків і винятки потрібно затвердити для кожного клієнта.","Картка охоплює подію зміни ролі; планові перегляди доступів і вихід працівника залишаються окремими процесами.","Ліцензії Microsoft Entra, доступність задач і затримки обробки залежать від цільової конфігурації та плану підписки.","Години попередні; джерела кадрових подій, кількість застосунків та інтерфейси відкликання уточнюють після аудиту."],"problems":["як перевірити доступи коли працівника переводять в інший відділ","як забрати старі права і видати нові після зміни посади","переведення працівника залишає доступ до систем попереднього відділу"],"synonyms":["employee mover access review","job change access transition","role change provisioning","переведення працівника","зміна посадових доступів"],"search_queries":["як прибрати доступ до старих систем після переведення співробітника","як видати потрібні групи коли змінився відділ працівника"],"sources":[{"type":"vendor_documentation","title":"Microsoft Entra: What are lifecycle workflows?","url":"https://learn.microsoft.com/en-us/entra/id-governance/what-are-lifecycle-workflows","checked_at":"2026-10-09","supports":"Визначає mover як окрему подію життєвого циклу працівника та описує доступи, групи, автоматизовані дії й журнал запусків."},{"type":"vendor_documentation","title":"Microsoft Entra: Automate employee mover tasks when they change jobs","url":"https://learn.microsoft.com/en-us/entra/id-governance/tutorial-mover-custom-workflow-portal","checked_at":"2026-10-09","supports":"Показує запуск workflow за зміною department, повідомлення керівника, відкладене зняття пакетних доступів і додавання до нової групи."},{"type":"vendor_documentation","title":"Microsoft Entra: Assign employee access deployment guide","url":"https://learn.microsoft.com/en-us/entra/architecture/governance-deployment-employee-access","checked_at":"2026-10-09","supports":"Описує рольові правила надання й відкликання пакетів доступу, погодження, перевірки доступу та окремі правила несумісних повноважень."},{"type":"inferred_pattern","title":"Редакційний сценарій переходу між профілями доступу","supports":"Порівняння старого й нового набору, контроль винятків і трудомісткість є проєктною моделлю; впровадження конкретного клієнта не перевірене."}],"status":"draft","variants":[{"id":"employee-mover-access-review-tracked","title":"Погодження і ручне підтвердження змін","description":"Кадрова подія формує перелік старих і нових прав; менеджери погоджують його, а адміністратор фіксує виконання по системах.","best_for":["Невеликої кількості переведень і систем без стабільних API для зміни груп."],"example":"Працівника переводять із закупівель до продажів. Керівники погодили нову групу CRM, відкликання доступу до закупівель та тимчасове право читання на 5 днів для передачі справ.","implementation_methods":["Зафіксувати зміну кадрових атрибутів і дату набрання чинності.","Порівняти матриці доступу старої та нової ролі й погодити відмінності.","Виконати й перевірити зміни у кожній системі окремо."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є власник кадрової події, каталог профілів доступу та відповідальні за системи."],"limitations":["Відкликання, надання й повторна перевірка лишаються ручними."],"pricing_modifiers":[]},{"id":"employee-mover-access-integrated","title":"Подієва синхронізація профілів доступу","description":"Перевірені конектори застосовують затверджені зміни до груп та пакетів доступу, фіксують результат і створюють задачі для систем без API.","best_for":["Кадрова система та основні каталоги ідентичностей мають перевірені API або журнали синхронізації."],"example":"Подія зміни підрозділу запустила перевірку профілів, зняла дві старі групи в дату переходу, додала погоджену групу продажів і залишила одну систему відкритим винятком для адміністратора.","implementation_methods":["Читати кадрові зміни з унікальним ID і підтримувати повторну доставку без дубльованих дій.","Обчислювати різницю між погодженими старими й новими профілями доступу.","Застосовувати, перечитувати й журналювати зміну кожного доступу окремо."],"complexity":"high","hours_min":42,"hours_max":84,"requirements":["Перевірені API, тестовий контур і призначені власники профілів доступу."],"limitations":["Системи без API потребують контрольованої ручної задачі; не можна вважати відсутність відповіді погодженням."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0086","reason":"Регулярний перегляд доступів шукає надлишкові права загалом. Ця картка запускається саме від кадрової зміни й порівнює старий та новий профілі."},{"type":"related","target_id":"AUT-0079","reason":"Завершення роботи працівника закриває доступи під час виходу. Ця картка обробляє переведення, коли працівник залишається в організації."},{"type":"related","target_id":"AUT-0042","reason":"Адаптація нового співробітника готує його до роботи. Ця картка змінює доступи чинного працівника при зміні посади чи підрозділу."}],"configurator_questions":[{"id":"employee-mover-access-multiple-systems","question":"Чи потрібно змінювати доступи більш ніж у трьох системах?","help_text":"Вкажіть системи, власників і спосіб підтвердження фактичних змін.","type":"boolean","required":true,"options":[],"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Додаються конектори або окремі контрольовані маршрути для додаткових систем."}]},{"id":"employee-mover-access-temporary-overlap","question":"Чи потрібні тимчасові старі доступи для передачі роботи?","help_text":"Потрібні власник винятку, дозволений обсяг прав і точна дата завершення.","type":"boolean","required":true,"options":[],"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додається погоджений виняток із датою завершення та перевіркою автоматичного відкликання."}]}]},{"schema_version":1,"id":"AUT-0463","slug":"workplace-near-miss-investigation-and-prevention","title":"Розбір небезпечної події без травмування","summary":"Повідомлення про подію без шкоди запускає перевірку небезпек, погодження запобіжних дій і контроль їх результату.","problem":"Працівники не повідомляють про небезпечні ситуації або повідомлення губляться. Команда не пов’язує повторні випадки й не перевіряє, чи усунули причину до наступної події.","outcome":"Кожна повідомлена подія має зафіксовані факти, рішення про термінові запобіжні дії, висновок відповідальних і перевірений результат погоджених заходів.","category":"security-compliance","subcategory":"audit","roles":["operations-manager","technician","owner"],"industries":["manufacturing","construction","logistics","cross-industry"],"triggers":["Працівник повідомив про небезпечну умову або подію, яка могла спричинити травму, пошкодження чи іншу шкоду, але шкоди не сталося."],"workflow_steps":["Негайну небезпеку передати відповідальному для усунення за чинним порядком. Реєстрація повідомлення не затримує захист людей чи обладнання.","Зафіксувати час, місце, джерело, опис без припущень і доступні докази. Повторні повідомлення зв’язати з подією, не стираючи відмінності у свідченнях.","Визначити, чи це справді подія без шкоди. Якщо з'явились відомості про травму, захворювання або обов’язкове повідомлення, передати випадок до окремої процедури.","Відповідальний класифікує небезпеку, визначає потрібних учасників розбору й тимчасові обмеження. Невідомі факти залишити непідтвердженими.","Разом із працівниками встановити безпосередні й системні чинники. Не закривати аналіз формулюванням про помилку людини без перевірки умов роботи, обладнання, інструкцій і навчання.","Погодити запобіжні дії, власників, строки й спостережувані критерії виконання. Розділити негайне стримування ризику та довгострокову зміну.","Прийняти докази виконання й окремо перевірити, чи діє новий контроль у роботі. Неефективні дії повернути на перегляд із причиною.","Повідомити працівникам висновки й застосовні зміни, не розкриваючи зайвих персональних даних. Переглядати повторювані типи небезпек за майданчиком і процесом, а не ранжувати людей."],"requirements":["Є відповідальний за охорону праці, порядок реагування на безпосередню небезпеку та критерії ескалації випадків зі шкодою.","Погоджені формат повідомлення, доступ до доказів, участь працівників і правила приватності.","Для запобіжних дій визначені власники, строки, докази завершення й спосіб перевірки результативності."],"limitations":["Це маршрут координації події без травмування. Реальне травмування або інша шкода потребує окремої процедури, допомоги та визначення належних повідомлень.","Закони, строки зовнішнього звітування й обов’язки роботодавця не визначаються матеріалами OSHA чи HSE; їх уточнює компетентний фахівець за місцем роботи.","Не можна робити висновок про вину, безпечність робочого місця чи достатність заходів лише на підставі заповненої форми.","Анонімний канал, доступ до свідчень і строки зберігання налаштовують за політикою організації та застосовними вимогами.","PlanFix може координувати записи, відповідальних, статуси та задачі; фізичні дії й спеціалізовані оцінки виконує уповноважена команда.","Години попередні; аудит вимог, фахове розслідування та впровадження фізичних засобів контролю не включені."],"problems":["як фіксувати небезпечні випадки без травм і перевіряти що зробили","працівник ледь не травмувався але незрозуміло як розібрати причину","повторюються небезпечні ситуації на виробництві а дії ніхто не перевіряє"],"synonyms":["near miss","near-miss reporting","повідомлення про подію без шкоди","небезпечне зближення"],"search_queries":["як розбирати небезпечну подію якщо ніхто не постраждав","як пов’язати повторні повідомлення про небезпеку та перевірити запобіжні дії"],"sources":[{"type":"vendor_documentation","title":"OSHA: Incident Investigation","url":"https://www.osha.gov/incident-investigation","checked_at":"2026-10-09","supports":"Рекомендація досліджувати події без травми, шукати небезпеки й системні причини та залучати працівників разом із керівниками. Це методична сторінка США, не норма українського права й не готова конфігурація."},{"type":"vendor_documentation","title":"HSE: Near-miss Book — Recording and reporting near misses at work","url":"https://www.hse.gov.uk/PUBNS/near-miss-book.htm","checked_at":"2026-10-09","supports":"HSE описує запис і аналіз таких повідомлень для пошуку повторюваних умов та раннього реагування. Публікація 2021 року не встановлює вимоги для України."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Задачі PlanFix можуть мати типи, поля, статуси й сценарії; це підтверджує можливість координувати записи та відповідальних, але не спеціалізоване розслідування чи фізичне усунення небезпеки."},{"type":"inferred_pattern","title":"Редакційна модель розбору подій без шкоди","supports":"Зв’язування повторів, розділення фактів і висновків, перевірка результату дій, питання, години та варіанти — проєктна модель для аудиту."}],"status":"draft","variants":[{"id":"near-miss-managed-review","title":"Керований розбір і контроль дій","description":"Відповідальна команда приймає повідомлення, документує аналіз і перевіряє запобіжні дії у погоджених задачах.","best_for":["Одна команда або майданчик із визначеним відповідальним і помірним потоком повідомлень."],"example":"Працівник повідомив про падіння коробки поруч із проходом без травми. Керівник локально огородив ділянку, команда зв'язала два схожі повідомлення й виявила нестабільне штабелювання. Після зміни правила зберігання відповідальний перевірив наступні обходи й додав доказ до тієї самої справи.","requirements":["Є захищене місце для повідомлень і власник перевірки кожної погодженої дії."],"implementation_methods":["Налаштувати тип задачі PlanFix з обмеженими полями, статусами, відповідальними та підзадачами для запобіжних дій.","Для повторів зберігати зв’язок із джерельними повідомленнями й не перезаписувати свідчення.","Вести рішення фахівця й докази перевірки результату окремими полями або пов'язаними задачами."],"complexity":"medium","hours_min":18,"hours_max":36,"pricing_modifiers":[],"limitations":["Автоматичне подання зовнішніх звітів і технічне усунення небезпеки не входять до цього варіанта."]},{"id":"near-miss-integrated-intake-and-trends","title":"Інтегрований збір і аналіз повторів","description":"Повідомлення з погоджених каналів створюють пов'язані справи; звіти показують повторювані типи небезпек і невиконані дії.","best_for":["Кілька майданчиків або значний потік повідомлень із затвердженими каналами збору та аналітики."],"example":"Форми з двох майданчиків передали повідомлення з унікальними номерами. Система об'єднала ймовірний повтор як пов'язаний випадок, але не видалила первинні записи; звіт показав одну незавершену дію та повтори навколо тієї самої операції.","requirements":["Визначені дозволені системи надходження, правила ідентифікації повторів, ролі доступу й актуальні довідники майданчиків."],"implementation_methods":["Імпортувати повідомлення з погоджених форм через перевірений API чи інтеграційний шлюз із захистом від повторного запису.","Відображати тенденції за типом небезпеки, процесом, майданчиком і статусом дії з урахуванням обмежень доступу.","Окремо зберігати первинні свідчення, рішення, версію класифікації та перевірку результативності."],"complexity":"high","hours_min":34,"hours_max":68,"pricing_modifiers":[],"limitations":["Якість групування повторів залежить від довідників і підтвердження відповідального; автоматичний збіг не встановлює однакову причину."]}],"dependencies":[{"type":"related","target_id":"AUT-0280","reason":"AUT-0280 координує справу після травмування; ця картка фіксує події без шкоди як окремий превентивний маршрут."},{"type":"related","target_id":"AUT-0281","reason":"Передавання зміни повідомляє наступну команду про відкриті роботи; розбір події встановлює причини й запобіжні дії."},{"type":"related","target_id":"AUT-0122","reason":"Перевірка коригувальної дії може підтвердити результат конкретного заходу; ця картка веде повний маршрут повідомлення про небезпечну подію без шкоди."}],"configurator_questions":[{"id":"near-miss-multiple-sites","question":"Чи потрібно вести повідомлення для кількох майданчиків?","help_text":"Уточніть окремих відповідальних, довідники локацій, доступ до деталей і спільну звітність.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Налаштувати маршрути, ролі та звіти за кількома майданчиками."}]},{"id":"near-miss-source-integration","question":"Чи потрібно автоматично приймати повідомлення із зовнішніх каналів?","help_text":"Погодьте джерело, захищені поля, ID повідомлення та поведінку при повторному надсиланні.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Додати погоджене джерело, інтеграцію, захист від повторів і перевірку доставки."}]}]},{"schema_version":1,"id":"AUT-0464","slug":"emergency-admin-access-validation-and-use-review","title":"Перевірка аварійного доступу адміністратора","summary":"Команда регулярно перевіряє працездатність резервного доступу та розбирає кожне його використання.","problem":"Резервний обліковий запис адміністратора створили на випадок відмови звичайного входу, але ніхто не перевіряє, чи він працює і чи сповіщення про використання доходить до команди.","outcome":"Для кожного аварійного облікового запису є актуальний список уповноважених, дата й результат погодженої перевірки, підтвердження сигналу моніторингу та окрема перевірка кожного реального використання.","category":"security-compliance","subcategory":"access","roles":["owner","operations-manager","technician"],"industries":["it-saas","professional-services","cross-industry"],"triggers":["Настав строк погодженого навчального тесту аварійного доступу або система моніторингу повідомила про його використання."],"workflow_steps":["Визначити облікові записи, власника контролю, уповноважених користувачів, джерело журналів та процедуру відновлення доступу.","До навчального тесту повідомити команду моніторингу про погоджений час і перевірити, що тест не буде сприйнятий як непогоджений інцидент.","Уповноважений адміністратор за затвердженою процедурою перевіряє вхід і потрібну контрольну дію. Система координації не зберігає секрети й не входить під привілейованим записом.","Перевірити фактичне отримання сигналу моніторингу, його одержувачів, часові мітки та зв'язок із запланованим тестом; пропущене сповіщення залишити відкритим винятком.","Оновити список уповноважених, підтвердити доступність захищеного способу отримання облікових даних і переглянути зміни в команді чи політиці входу.","Кожний позаплановий сигнал створює окремий терміновий випадок для відповідального. Він зберігає посилання на журнали, з'ясовує підставу та перевіряє виконані адміністративні дії.","Погодити результат: санкціоноване використання, навчальний тест або невирішена подія; невідомий користувач чи неповний журнал потребує ескалації.","За рішенням відповідального оновити процедуру, контроль або спосіб зберігання секретів. Не закривати випадок тільки тому, що доступ згодом відновили.","Зберігати дату, учасників, результат і посилання на журнал за погодженим строком; не копіювати пароль, ключ чи код другого фактора до задачі або сповіщення."],"requirements":["Є документована аварійна процедура, окремо визначені уповноважені й захищене місце зберігання облікових даних.","Погоджені строк тестування, безпечна контрольна дія, спосіб попередження моніторингу та критерії успіху.","Доступні журнали входу й аудиту або призначений відповідальний, який перевіряє їх у джерельній системі.","Визначені терміновість сповіщення, ескалація невідомого використання та правила збереження доказів."],"limitations":["Microsoft радить щонайменше два аварійні облікові записи та перевірку не рідше ніж раз на 90 днів для Microsoft Entra; це рекомендація вендора для його середовища, не універсальна норма.","Не створює резервні облікові записи, не змінює політики автентифікації й не виконує тестовий вхід замість уповноваженого адміністратора.","Не зберігає паролі, секрети, коди MFA чи особисті пристрої; матеріали моніторингу залишаються у джерельній системі з її правами доступу.","Сповіщення не доводить, що всі журнали повні або що використання було безпечним; людина перевіряє події та адміністративні дії.","PlanFix може координувати графік, відповідальних, винятки та посилання на докази; робота з обліковим записом і журнали потребують окремої системи ідентичності та моніторингу.","Години попередні; налаштування IAM, моніторингу, безпечного сховища та відновлення доступу не включені."],"problems":["як перевіряти аварійний доступ адміністратора і сповіщення про його використання","резервний адмін акаунт може не працювати коли заблоковані звичайні входи","хто перевіряє аварійний обліковий запис та розбирає його використання"],"synonyms":["emergency access account","break-glass account","аварійний обліковий запис","резервний доступ адміністратора"],"search_queries":["як регулярно перевіряти аварійний доступ адміністратора та сповіщення про його використання","як розібрати вхід у резервний обліковий запис адміністратора"],"sources":[{"type":"vendor_documentation","title":"Microsoft Entra: Manage emergency access accounts","url":"https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/security-emergency-access","checked_at":"2026-10-09","supports":"Вимагає документовану процедуру, моніторинг кожного входу, регулярну перевірку працездатності й післяподієвий розбір. Microsoft наводить власні вимоги для Entra, включно з інтервалом до 90 днів; вони не переносяться автоматично на інші продукти чи юрисдикції."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Тип задачі може містити поля й статуси та використовувати сценарії; це дає основу для координації перевірок і винятків, але не підтверджує читання журналів IAM або зберігання секретів у PlanFix."},{"type":"inferred_pattern","title":"Редакційна модель перевірки аварійного доступу","supports":"Пов'язування планового тесту з окремим інцидентом, контроль сповіщень, критерії перевірки, питання та оцінка є проєктною моделлю для аудиту."}],"status":"draft","variants":[{"id":"emergency-access-manual-validation","title":"Планова перевірка з ручним розбором сигналів","description":"Адміністратор виконує контрольний вхід за процедурою, а відповідальна команда вручну звіряє журнал і сповіщення.","best_for":["Невелика команда з окремим відповідальним за моніторинг та одним середовищем ідентичності."],"example":"Під час квартальної перевірки адміністратор підтвердив вхід і тестову дію. Черговий побачив узгоджений сигнал у журналі, звірив одержувачів сповіщення й зафіксував результат без копіювання секрету до задачі.","requirements":["Є погоджений календар перевірки, інструкція та працівник, який незалежно підтверджує сигнал."],"implementation_methods":["Створювати повторювану задачу PlanFix із датою перевірки, відповідальними, контрольним списком і посиланням на журнал.","Перед запланованим тестом сповіщати команду моніторингу окремим погодженим каналом.","Зберігати результат і винятки без значень облікових даних."],"complexity":"medium","hours_min":18,"hours_max":36,"pricing_modifiers":[],"limitations":["Журнали перевіряють вручну; невідомий сигнал потребує термінового ручного розбору."]},{"id":"emergency-access-integrated-monitoring","title":"Подієве сповіщення та контроль тестів","description":"Моніторинг передає сигнал входу у погоджений маршрут, а планові перевірки контролюють фактичне сповіщення та післяподієве рішення.","best_for":["Кілька середовищ або чергова команда з доступними журналами, автоматичними сповіщеннями та погодженим моніторингом."],"example":"Журнал Entra зафіксував використання аварійного запису. Інтеграція створила термінову задачу з ID події, часом і посиланням на джерело. Черговий класифікував сигнал як санкціоновану аварію, перевірив журнал дій і зафіксував рішення.","requirements":["Підтверджений канал доставки журналів, одержувачі сигналу, унікальний ID події та тестовий маршрут."],"implementation_methods":["Читати тільки погоджені поля журналу; не передавати пароль, код MFA чи надлишкові персональні дані.","Створювати одну задачу на унікальний ID входу й перевіряти доставку та повторні події.","Зв'язувати планові тести, журнали сигналу, післяподієве рішення й відкриті заходи."],"complexity":"high","hours_min":36,"hours_max":72,"pricing_modifiers":[],"limitations":["Конкретний API, затримка журналу та повнота подій залежать від IAM і моніторингу; це перевіряють перед підключенням."]}],"dependencies":[{"type":"related","target_id":"AUT-0086","reason":"Періодичний перегляд оцінює багато чинних доступів; ця картка перевіряє спеціально підготовлені аварійні записи, працездатність входу й реакцію на кожне використання."},{"type":"related","target_id":"AUT-0146","reason":"Тимчасовий доступ має обмежений строк і перевірене відкликання; аварійний запис є постійним резервом і потребує тесту та моніторингу."},{"type":"related","target_id":"AUT-0087","reason":"Реагування на інцидент безпеки захищає ресурси після підтвердженої події; ця картка запускає перевірку від сигналу аварійного облікового запису й звіряє його призначення."}],"configurator_questions":[{"id":"emergency-access-multiple-environments","question":"Чи потрібно вести аварійні записи для кількох окремих середовищ?","help_text":"Погодьте власника, джерело журналів, чергу сповіщень і процедуру для кожного середовища.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Додати маршрути, ролі та звірку сигналів для кількох ізольованих середовищ."}]},{"id":"emergency-access-log-integration","question":"Чи потрібно автоматично створювати випадок з журналу входу?","help_text":"Перевірте API або шлюз журналів, унікальний ID події, затримку доставки та підтвердження сигналу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Підключити журнал входу, захист від повторів, маршрут терміновості та контроль доставки."}]}]},{"schema_version":1,"id":"AUT-0465","slug":"risk-based-critical-medical-device-supplier-audit","title":"Планування та контроль аудиту критичного постачальника медичних виробів","summary":"Виробник планує ризик-орієнтовані аудити критичних постачальників і зберігає перевірний зв’язок між планом, доказами, висновками та подальшими діями.","problem":"Плани й звіти аудитів постачальників розпорошені між календарями, поштою та папками. Команда не бачить, чому обрала постачальника, чи охопив аудит потрібні процеси та чи доступні записи для наступного перегляду.","outcome":"Для кожного запланованого аудиту є обґрунтований пріоритет, погоджені межі й критерії, кваліфіковані учасники, збережені докази та звіт із контрольованими подальшими рішеннями.","category":"production","subcategory":"quality-control","roles":["procurement-specialist","operations-manager","owner"],"industries":["healthcare","manufacturing"],"triggers":["Настав строк затвердженого аудиту постачальника критичного продукту або процесу.","Новий ризик, зміна постачальника чи повторні проблеми потребують переглянути пріоритет аудиту."],"workflow_steps":["Визначити постачальника, продукцію або аутсорсинговий процес, пов’язаний продукт і відповідального за програму аудиту.","Застосувати затверджені критерії ризику й результативності постачальника; записати причину вибору та межі аудиту.","Погодити мету, критерії, майданчик або формат, дату, команду та компетентність аудиторів; перевірити незалежність, коли вона потрібна.","Надіслати погоджений план постачальнику та зібрати лише необхідні попередні записи в сховищі з відповідними правами.","Провести аудит за затвердженим планом; фіксувати фактичні докази, вибірки та посилання на контрольовані записи.","Звірити факти з критеріями, надати постачальнику можливість уточнити фактичні помилки й випустити контрольований звіт.","Призначити власників і строки подальших дій; передати конкретну невідповідність до окремого процесу коригувальних дій постачальника.","Уповноважений фахівець оцінює завершення, ефективність і потребу змінити статус чи частоту контролю постачальника; зберегти рішення та записи за погодженим строком."],"requirements":["Визначені критерії критичності, пріоритету й частоти аудиту, власник програми та повноваження щодо статусу постачальника.","Є актуальні дані про продукцію, закупівлі, скарги, невідповідності та попередні оцінки в авторитетних системах.","Визначені компетентні аудитори, доступ до записів, правила конфіденційності й контрольоване сховище звітів.","Затверджені межі аудиту, критерії, формат звіту, строки відповіді та маршрут подальших дій."],"limitations":["FDA вказує, що за QMSR, чинним із 2 лютого 2026 року, інспектори можуть переглядати звіти аудитів постачальників. Це твердження стосується продукції під наглядом FDA.","MDSAP Audit Approach є методичним документом програми для медичних виробів і юрисдикцій-учасниць; він не встановлює універсального календаря аудиту для всіх постачальників.","PlanFix може координувати план, задачі, строки й відповідальних. Він не проводить аудит, не надає кваліфікацію аудитора та не є сховищем доказів без окремого аналізу доступу й конфіденційності.","Оцінка не включає проведення аудиту, відрядження, зовнішніх аудиторів, юридичний висновок чи сертифікацію; попередня."],"problems":["аудити постачальників прострочуються","звіти аудитів постачальників важко знайти","немає контролю аудиту критичного постачальника"],"synonyms":["аудит постачальника медичних виробів","перевірка постачальника медичних виробів","аудит критичного постачальника"],"search_queries":["як планувати аудит критичного постачальника медичних виробів","де контролювати звіти та висновки аудиту постачальника","як не пропустити повторний аудит виробника медичного обладнання"],"sources":[{"type":"vendor_documentation","title":"FDA: Quality Management System Regulation — Frequently Asked Questions","url":"https://www.fda.gov/medical-devices/quality-management-system-regulation-qmsr/quality-management-system-regulation-frequently-asked-questions","checked_at":"2026-10-09","supports":"Пункти 7–8 пояснюють, що з 2 лютого 2026 року FDA може переглядати записи системи якості, включно зі звітами аудитів постачальників. Це стосується інспекцій FDA та медичних виробів у її юрисдикції."},{"type":"vendor_documentation","title":"FDA: MDSAP Audit Approach, Chapter 7 — Purchasing","url":"https://www.fda.gov/media/157947/download","checked_at":"2026-10-09","supports":"Завдання 2 розділу закупівель описує вибір файлу оцінювання постачальника для аудиту та пріоритет за ризиком; наступні завдання розглядають критерії вибору, оцінювання й повторного оцінювання. Це методика MDSAP, а не універсальна вимога до всіх компаній."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Тип задачі може мати власні поля, статуси та сценарії. Це підтверджує можливість координувати внутрішній план і строки після налаштування; не підтверджує проведення аудиту чи керування регуляторними записами."},{"type":"inferred_pattern","title":"Робоча модель координації аудиту постачальника","supports":"Структуру плану, ролей, доказів, звіту та наступного рішення потрібно узгодити з системою якості, ризиками й юрисдикціями конкретного виробника. Оцінки годин є проєктними гіпотезами для аудиту."}],"status":"draft","variants":[{"id":"supplier-audit-coordination","title":"Координація аудиту та контрольованих записів","description":"Команда веде календар, межі, учасників і статус звіту, а докази зберігає у чинному контрольованому сховищі.","best_for":["Один майданчик і обмежена кількість аудитів, де записи вже мають затверджене сховище."],"example":"Після перегляду повторних невідповідностей власник програми призначив аудит постачальника стерильного компонента. Задача містила обґрунтування пріоритету, план, відповідальних і посилання на звіт у контрольованому сховищі.","requirements":["Є затверджена програма аудитів, критерії ризику й доступне контрольоване сховище."],"implementation_methods":["Налаштувати в PlanFix тип задачі з постачальником, обсягом, ризиком, строками, аудиторами, статусом звіту та посиланням на сховище.","Створювати повторну задачу за погодженою датою; прострочення й відкриті висновки передавати власнику програми.","Зберігати затверджений план, звіт і докази у контрольованій системі якості; у PlanFix залишати лише необхідні посилання."],"complexity":"medium","hours_min":24,"hours_max":48,"pricing_modifiers":[],"limitations":["Збір аудиторських доказів, висновки й погодження виконують фахівці; інтеграції зі сховищем не включені."]},{"id":"supplier-audit-risk-program","title":"Ризик-орієнтована програма для кількох майданчиків","description":"Дані оцінювання, невідповідностей і графіків пов’язують у звітність; маршрути й права перевіряють для кожного джерела.","best_for":["Кілька майданчиків, багато критичних постачальників і наявні цифрові джерела оцінок та звітів."],"example":"Якість оновила пріоритет постачальника після повторної невідповідності. Інтеграція сформувала проєкт задачі аудиту з джерельними ID, а власник підтвердив межі, аудитора та календар перед надсиланням плану.","requirements":["Джерела мають стабільні ID, узгоджені поля ризику, API або експорт, власників даних і погоджений контроль доступу."],"implementation_methods":["Перевірити джерела оцінок, закупівель і якості; узгодити правила зіставлення постачальників та журнал змін.","Автоматизувати чернетки задач і нагадування, залишивши затвердження вибору, меж і висновків за фахівцем.","Перевірити права на звіти, повторні записи, відмови інтеграції та повноту посилань на докази."],"complexity":"high","hours_min":48,"hours_max":96,"pricing_modifiers":[],"limitations":["Складність інтеграції та права на сторонні аудиторські записи перевіряють окремо; автоматизоване рішення про відповідність не передбачене."]}],"dependencies":[{"type":"related","target_id":"AUT-0369","reason":"AUT-0369 перевіряє допуск постачальника до конкретної закупівлі; ця картка планує аудит і зберігає його докази та звіт."},{"type":"related","target_id":"AUT-0437","reason":"AUT-0437 контролює відповідь на конкретний дефект і план коригувальних дій; ця картка охоплює аудит, а окремі висновки передає туди для подальшої обробки."}],"configurator_questions":[{"id":"supplier-audit-multiple-sites","question":"Чи потрібно координувати аудити для кількох майданчиків?","help_text":"Кількість майданчиків впливає на календарі, ролі, звітність і права доступу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додати окремі маршрути, календарі й звітність для кількох майданчиків."}]},{"id":"supplier-audit-source-integration","question":"Чи потрібно отримувати оцінки або записи аудиту з ERP/QMS?","help_text":"Потрібні системи, стабільні ID, доступні поля та правила обробки змін.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Додати одне погоджене джерело, зіставлення записів і перевірку обміну."}]}]},{"schema_version":1,"id":"AUT-0466","slug":"medical-device-gudid-record-submission-control","title":"Підготовка й контроль запису медичного виробу для GUDID","summary":"Власник даних перевіряє ідентифікатор та атрибути медичного виробу, погоджує подання до GUDID і зберігає підтвердження прийняття запису.","problem":"Дані про виріб, версію моделі та маркування надходять із різних систем. Через це запис GUDID може бути неповним або не збігатися із затвердженим маркуванням, а команда не має перевірного підтвердження подання.","outcome":"Кожне нове або змінене подання має джерела даних, узгоджений DI, відповідального labeler, погоджену версію запису, перевірений результат передачі та журнал виправлень.","category":"production","subcategory":"quality-control","roles":["operations-manager","technician","owner"],"industries":["healthcare","manufacturing"],"triggers":["Labeler готує новий запис DI для виробу або пакування, що підпадає під UDI Rule FDA.","Зміна моделі, атрибутів чи маркування вимагає переглянути наявний запис GUDID."],"workflow_steps":["Підтвердити роль labeler, ринок збуту, застосовні правила, винятки та відповідального за запис; не припускати застосовність FDA до інших юрисдикцій.","Зв’язати затверджені дані про модель і пакування з ідентифікатором DI та джерелом кожного потрібного атрибута.","Звірити назву, версію, тип пакування, компанію та інші поля з актуальною таблицею елементів GUDID; відсутні або суперечливі значення передати власникам джерел.","Перевірити відповідність запису затвердженому маркуванню та вимогам уповноваженим фахівцем; не генерувати DI без акредитованого issuing agency.","Обрати ручний вебзастосунок для поодинокого DI або погоджене подання HL7 SPL через FDA Electronic Submissions Gateway для масового пакета; для SPL підтвердити облікові записи й завершене тестування.","Передати погоджену версію, зафіксувати контрольний ідентифікатор, файл або квитанцію та прийнятий чи відхилений статус.","Для відхиленого запису створити контрольоване виправлення, повторно перевірити зміни й не вважати задачу завершеною за фактом надсилання.","Звірити опублікований DI у відкритому AccessGUDID або джерельному підтвердженні, зберегти дату та версію результату; зберігати PI у виробничому обліку, а не в GUDID."],"requirements":["Визначені labeler, ринки, застосовність UDI Rule, призначені ролі GUDID та уповноважений reviewer.","Є затверджені модель і маркування, DI від відповідного issuing agency та авторитетні джерела потрібних атрибутів.","Актуальні елементи даних і правила перевірки доступні для потрібної версії запису.","Для масового HL7 SPL подання налаштовані акаунти FDA ESG і GUDID та завершені потрібні випробування."],"limitations":["FDA вимагає UDI на маркуванні й подання даних до GUDID для виробів у сфері UDI Rule з урахуванням застосовних винятків та альтернатив; не переносити це на всі ринки.","GUDID містить Device Identifier (DI), але не Production Identifier (PI). Партію, серійний номер, дату виготовлення та строк придатності ведуть у відповідних виробничих і логістичних записах.","FDA описує ручне внесення поодиноких DI та пакетне подання HL7 SPL через ESG. Це не означає, що GUDID надає звичайний API або що будь-яка інтеграція вже доступна.","PlanFix може координувати власників, строки, погодження та посилання на контрольовані записи; він не є GUDID, issuing agency чи авторитетною системою маркування.","Години попередні. Юридична класифікація, вибір DI, точність маркування та схвалення запису залишаються відповідальністю фахівців."],"problems":["як підготувати і перевірити запис виробу для GUDID","як контролювати подання UDI до бази FDA після зміни моделі","як знайти помилку в даних медичного пристрою перед GUDID"],"synonyms":["GUDID submission","UDI device identifier record","FDA GUDID record","подання DI до GUDID","ідентифікатор виробу FDA"],"search_queries":["як контролювати подання даних медичного виробу до GUDID після зміни етикетки","як звірити DI пристрою з його маркуванням та записом FDA","як підтвердити прийняття пакета HL7 SPL для медичних виробів"],"sources":[{"type":"vendor_documentation","title":"FDA: UDI Basics","url":"https://www.fda.gov/medical-devices/unique-device-identification-system-udi-system/udi-basics","checked_at":"2026-10-09","supports":"FDA описує DI як обов’язкову фіксовану частину UDI, PI як умовну змінну частину; GUDID містить тільки DI. Вимоги стосуються labeler і виробів у сфері правила FDA з винятками, а не кожного ринку."},{"type":"vendor_documentation","title":"FDA: Submit Data to GUDID","url":"https://www.fda.gov/medical-devices/global-unique-device-identification-database-gudid/submit-data-gudid","checked_at":"2026-10-09","supports":"Офіційна сторінка описує ручне внесення одиничних DI через GUDID web application та пакетні файли HL7 SPL через FDA Electronic Submissions Gateway. Для SPL потрібні облікові записи й тестування."},{"type":"vendor_documentation","title":"FDA: Prepare for GUDID","url":"https://www.fda.gov/medical-devices/global-unique-device-identification-database-gudid/prepare-gudid","checked_at":"2026-10-09","supports":"FDA радить організувати й перевірити дані, визначити ролі, зібрати атрибути та вибрати варіант подання; підготовка потребує координації даних у кількох системах."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Поля, статуси й сценарії задач можуть координувати внутрішні погодження та строки після конфігурації. Документація не підтверджує прямої інтеграції PlanFix із GUDID або FDA ESG."},{"type":"inferred_pattern","title":"Редакційна модель контролю подання GUDID","supports":"Зіставлення джерел, маршрут погодження, перевірка квитанції та збереження версій — проєктна модель для аудиту. Оцінки не підтверджені впровадженням клієнта."}],"status":"draft","variants":[{"id":"gudid-single-record-review","title":"Ручне подання та перевірка одиничних записів","description":"Фахівець узгоджує поля з контрольованими джерелами, вносить DI через GUDID web application та перевіряє результат.","best_for":["Небагато нових чи змінених DI та можливість вручну працювати з порталом GUDID."],"example":"Власник моделі надав затверджені характеристики й DI від issuing agency. Reviewer знайшов відсутнє значення пакування, повернув запис на уточнення, а після ручного подання зберіг підтвердження й звірив публічний запис.","requirements":["Є користувачі GUDID, затверджені дані та reviewer, уповноважений підтвердити запис."],"implementation_methods":["Створювати задачу з DI, джерелами атрибутів, версією запису й контрольним списком для reviewer.","Передавати затверджене значення до GUDID web application уповноваженим labeler-користувачем.","Зберігати квитанцію, дату й результат перевірки публічного DI; PI залишати в системі партій або серійного обліку."],"complexity":"medium","hours_min":20,"hours_max":40,"pricing_modifiers":[],"limitations":["Внесення виконує людина; автоматичне створення або подання DI не включене."]},{"id":"gudid-bulk-spl-review","title":"Пакетне подання HL7 SPL із контрольованою звіркою","description":"Команда формує узгоджений набір записів із джерел даних, готує та перевіряє SPL і підтверджує результат через FDA ESG.","best_for":["Багато DI, стабільні джерела даних, уповноважена команда й налаштовані акаунти та тестування FDA ESG."],"example":"Зміна лінійки торкнулася кількох моделей. Інтеграційна команда зіставила DI та атрибути з системи життєвого циклу виробу, відхилила неповні рядки, а reviewer погодив валідований пакет SPL до передачі через ESG.","requirements":["Для ESG завершені реєстрація й тестування; підтверджено формат даних, унікальні DI, джерельні ID та порядок повторної передачі."],"implementation_methods":["Зіставити затверджений product master із таблицею полів GUDID і перевірити походження значень.","Сформувати SPL за вимогами FDA, виконати тестування та передати пакет тільки після ручного погодження.","Зіставити результат ESG із кожним DI, повернути відхилені записи на виправлення й зберегти версію файлу та квитанції."],"complexity":"high","hours_min":48,"hours_max":96,"pricing_modifiers":[],"limitations":["Вимагає окремого тестованого контуру FDA ESG; схема та правила подання мають відповідати актуальним вимогам FDA."]}],"dependencies":[{"type":"related","target_id":"AUT-0186","reason":"AUT-0186 контролює внутрішній довідник сканованих штрихкодів та одиниць товару. Ця картка готує DI-запис до GUDID і не виводить PI з товарного штрихкоду."},{"type":"related","target_id":"AUT-0263","reason":"AUT-0263 веде регуляторну оцінку повідомлення після інциденту з медичним виробом. Ця картка забезпечує точність і підтвердження запису DI до виникнення такого випадку."}],"configurator_questions":[{"id":"gudid-source-systems","question":"Чи надходять дані атрибутів із кількох систем?","help_text":"Визначте, де зберігаються модель, маркування, пакування, DI та значення полів GUDID.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Додати зіставлення джерел, правила пріоритету та перевірку конфліктів."}]},{"id":"gudid-multiple-labelers","question":"Чи потрібно координувати записи кількох юридичних осіб-labeler?","help_text":"Потрібні окремі акаунти, ролі, власники DI та погодження для кожної організації.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додати маршрути, розмежування власників та окреме підтвердження для кожного labeler."}]}]},{"schema_version":1,"id":"AUT-0467","slug":"positive-pay-check-exception-review","title":"Розгляд винятків Positive Pay для виданих чеків","summary":"Фінансист перевіряє чекові винятки банку за реєстром виданих чеків і передає своєчасне погоджене рішення уповноваженому користувачу банку.","problem":"Банк показує чек, який не збігся з реєстром виданих чеків, але сповіщення губиться або рішення приймають без перевірки рахунку, номера, суми, отримувача та підстави виплати.","outcome":"Кожний виняток має джерельний запис, причину розбіжності, доказ перевірки, уповноваженого погоджувача, передане до банку рішення та підтверджений результат до банківського строку.","category":"finance","subcategory":"payments","roles":["finance-specialist","owner","operations-manager"],"industries":["manufacturing","wholesale","professional-services","cross-industry"],"triggers":["Банк надіслав Positive Pay виняток щодо чека, якого немає у файлі видачі або чиї реквізити не збіглися.","Потрібно перевірити повторний номер, суму, статус скасування, дату чи ім’я отримувача до рішення банку."],"workflow_steps":["Отримати виняток із банківського порталу або погодженого каналу та записати рахунок, номер чека, суму, дату, отримувача, причину й строк рішення.","Зіставити його з авторитетним реєстром випущених і скасованих чеків, затвердженим рахунком постачальника, рахунком-фактурою та документом погодження.","Якщо доступне зображення, перевірити лицьовий і зворотний бік, отримувача, індосамент і ознаки зміни; невідомий, дубльований або змінений чек передати на ескалацію.","Визначити маршрут: підтверджений чек, виправлення файлу видачі, перевірка скасування або потенційне шахрайство. Не створювати оплату з задачі й не змінювати банківський запис автоматично.","За розділенням обов’язків фінансовий reviewer перевіряє висновок, а окремий уповноважений користувач ухвалює `pay` або `return` у порталі банку до фактичного строку.","Зафіксувати рішення, підставу, особу, час і банківське підтвердження; якщо рішення не передано, негайно ескалувати за фактичною політикою банку.","Після обробки звірити результат із банківським звітом і реєстром видачі; несподіване проведення повідомити банку й передати до окремого процесу реагування на платіжне шахрайство.","Зберігати лише потрібні метадані й захищені посилання на зображення; не копіювати повний номер рахунку або банківські облікові дані в загальні задачі."],"requirements":["Банк пропонує Positive Pay для рахунку та повідомляє чинні формати реєстру, типи винятків, строки й наслідки відсутності рішення.","Є повний і актуальний реєстр чеків, ідентифікатори рахунків, одержувачі, суми, причини видачі та статуси скасування.","Визначені різні ролі підготовки, перевірки та банківського рішення; доступ до зображень і фінансових даних обмежено.","Погоджені порядок перевірки підозрілих винятків, резервний контакт банку, часовий пояс та канал ескалації до cut-off."],"limitations":["Positive Pay, payee matching, типи винятків, строки й результат бездіяльності залежать від конкретного банку, рахунку та договору; не задавати універсальне рішення за замовчуванням.","Банк зіставляє представлені чеки з реєстром клієнта й показує невідповідності; фінансовий фахівець має визначити, чи платити або повертати чек.","PlanFix може координувати відповідальних, дедлайн, докази й ескалацію. Остаточне рішення виконує уповноважений користувач у банківському каналі.","Не підключає банківський портал без окремого підтвердженого інтерфейсу й правил безпеки; не гарантує відшкодування збитків.","Години попередні; доступність функцій, обсяг чеків, кількість рахунків і спосіб передавання даних потрібно перевірити з банком."],"problems":["як перевіряти підозрілі чеки у Positive Pay до списання з рахунку","банк надіслав виняток щодо чека кому його погодити і до якого строку","як звірити чек який банк не знайшов у реєстрі виданих оплат"],"synonyms":["positive pay exception","check issue file","payee positive pay","виняток перевірки чека","перевірка виданих чеків у банку"],"search_queries":["як погоджувати винятки Positive Pay щодо суми або отримувача чека","як вчасно передати банку рішення оплатити чи повернути підозрілий чек","як звірити представлений банку чек із реєстром виданих оплат"],"sources":[{"type":"vendor_documentation","title":"U.S. Bank: Cash Risk Management Solutions","url":"https://www.usbank.com/corporate-and-commercial-banking/solutions/liquidity-and-investments/cash-risk-management.html","checked_at":"2026-10-09","supports":"U.S. Bank описує електронне зіставлення представлених чеків із файлом виданих інструментів; невідповідності стають винятками, щодо яких клієнт приймає рішення оплатити або повернути. Умови стосуються конкретної пропозиції банку."},{"type":"vendor_documentation","title":"U.S. Bank: Fraud Prevention Checklist","url":"https://www.usbank.com/corporate-and-commercial-banking/insights/risk/mitigation/fraud-prevention-checklist.html","checked_at":"2026-10-09","supports":"Банк радить щодня переглядати чекові й payee-винятки та приймати рішення. Перелік є описом його продукту, а не універсальним SLA для всіх банків."},{"type":"vendor_documentation","title":"Bank of America: Check Positive Pay Fact Sheet","url":"https://images.em.bankofamerica.com/GTS/Payments/Check_Positive_Pay_Fact_Sheet.PDF","checked_at":"2026-10-09","supports":"Описує зіставлення номера, суми й за доступного сервісу payee, перегляд зображень, ролі decision-maker та подання рішення до банківського дедлайну. Список функцій залежить від підписаної послуги."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Налаштований тип задачі може мати власні поля, статуси та автоматизовані сценарії. Це підтверджує внутрішню координацію винятків, а не з’єднання з порталом банку."},{"type":"inferred_pattern","title":"Редакційна модель незалежної перевірки чекових винятків","supports":"Зіставлення реєстру, розподіл обов’язків, ескалація та попередні трудовитрати є проєктною моделлю для аудиту конкретного банку й ERP."}],"status":"draft","variants":[{"id":"positive-pay-manual-exception-control","title":"Ручний розгляд із банківським рішенням","description":"Фінансист приймає сповіщення, звіряє його з ERP і доказами, а уповноважений працівник вносить рішення в портал банку.","best_for":["Один банк і небагато винятків, які можна своєчасно перевірити вручну."],"example":"Банк знайшов чек на 18 400 USD без збігу в issue file. Фінансист перевірив номер, суму й отримувача за затвердженим рахунком, не знайшов дозволу на видачу й передав підтверджене рішення `return` авторизованому користувачу до банківського строку.","requirements":["Є доступ до порталу банку, актуальний реєстр чеків і резервний відповідальний на час відсутності основного."],"implementation_methods":["Вести задачу з банківським ID винятку, рахунком, номером чека, сумою, причиною та часом cut-off.","Додати контрольний список джерел звірки й окремі ролі reviewer та банківського approver.","Зберігати обране рішення, час передачі й ідентифікатор банківського підтвердження; звірити його наступним звітом."],"complexity":"medium","hours_min":16,"hours_max":32,"pricing_modifiers":[],"limitations":["Користувачі вносять і перевіряють винятки вручну; у разі високого обсягу потрібен додатковий контроль зміни."]},{"id":"positive-pay-integrated-issue-and-exception-control","title":"Передавання issue file та маршрутизація винятків","description":"Погоджений файл видачі передається банку через підтриманий канал, а винятки формують чергу з дедлайном і підтвердженням.","best_for":["Кілька рахунків або регулярний обсяг чеків за наявності банківського формату, інтеграційного каналу й стабільного джерела даних."],"example":"ERP передала денний issue file. Контроль відхилив рядок без рахунку, а два bank exceptions створили окремі задачі з банківським cut-off. Задачі не виставили рішення автоматично; фінансові approvers внесли його в банку й підтвердили статус.","requirements":["Банк підтвердив канал передачі, формат issue/paid file, календар, дедлайни й призначені користувацькі права."],"implementation_methods":["Зіставити ERP-файл із банківським форматом та перевірити кількість рядків, суми, дублі й контрольні totals перед відправленням.","Приймати винятки за унікальним ID, ставити cut-off і маршрутизувати їх за рахунком та сумою без автоматичного рішення pay/return.","Повторно читати банківський статус та звіряти його з ERP; помилки доставки, запізнення й невідомі статуси блокувати для ручного розбору."],"complexity":"high","hours_min":32,"hours_max":64,"pricing_modifiers":[],"limitations":["Технічний канал, SLA, формати й можливість читати exceptions залежать від банку та мають бути перевірені до оцінки інтеграції."]}],"dependencies":[{"type":"related","target_id":"AUT-0406","reason":"AUT-0406 розбирає сторнування чека, який уже видали. Positive Pay починається з винятку чека, пред’явленого банку, і рішення до оплати."},{"type":"related","target_id":"AUT-0116","reason":"Звірка банківського рахунку пояснює рухи після проведення; Positive Pay перевіряє виняток до рішення банку щодо пред’явленого чека."}],"configurator_questions":[{"id":"positive-pay-multiple-accounts","question":"Чи потрібно вести винятки для кількох банківських рахунків?","help_text":"Потрібно звірити окремі ролі, часові пояси, календарі та дедлайни кожного рахунку.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додати конфігурацію рахунків, власників, дедлайнів і звітність за кожним банківським каналом."}]},{"id":"positive-pay-file-integration","question":"Чи потрібно передавати issue file та отримувати винятки автоматично?","help_text":"Спочатку підтвердьте з банком формат, підтриманий канал, тестування й права користувачів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Додати одну погоджену інтеграцію файлів, перевірку totals, повторів і статусів доставки."}]}]},{"schema_version":1,"id":"AUT-0468","slug":"employee-compensation-review-followup","title":"Контроль обіцяного перегляду умов оплати працівника","summary":"Керівник отримує нагадування про індивідуальний перегляд оплати, фіксує рішення та наступну дату з доступом лише для уповноважених осіб.","problem":"Керівник обіцяв повернутися до умов оплати через кілька місяців, але забув дату. Працівник чекає, а команда не бачить, чи перегляд відбувся та хто має ухвалити рішення.","outcome":"Кожний запланований перегляд має працівника, відповідального, строк, зафіксоване рішення та наступну дату. Прострочення видно керівнику; погоджену зміну передають окремому кадровому процесу.","category":"hr","subcategory":"workforce","roles":["owner","hr-specialist","operations-manager"],"industries":["cross-industry","e-commerce","professional-services"],"triggers":["Наближається індивідуальна дата перегляду оплати, визначена в домовленості з працівником.","Керівник погодив нову дату після завершення попереднього перегляду."],"workflow_steps":["Пов’язати перегляд із працівником, чинними умовами, обіцяною датою та відповідальним; перевірити, чи вже існує відкритий перегляд цієї домовленості.","Надати доступ лише працівникам кадрової служби та уповноваженим керівникам; перевірити його після зміни підпорядкування.","До строку нагадати відповідальному й запросити обґрунтування пропозиції; прострочений перегляд показати в окремій черзі.","Передати конкретну пропозицію погоджувачу. Зафіксувати рішення: змінити умови, залишити чинні або перенести перегляд із причиною та новою датою.","Зберегти підтвердження повідомлення працівника та наступну дату перегляду; рішення про зміну передати в процес введення умов із датою чинності.","Закрити перегляд після фіксації рішення й наступного кроку; зберегти попередні домовленості без перезаписування їх історії."],"requirements":["Є узгоджені індивідуальні дати, власник перегляду та уповноважений погоджувач.","Визначено джерело чинних умов, правила доступу й порядок повідомлення працівника.","Кадрові та фінансові дані зберігаються в погодженому захищеному контурі."],"limitations":["Перегляд не гарантує підвищення та не визначає ринковий рівень зарплати автоматично.","Нарахування зарплати, виплата й фактичне введення нової ставки потребують окремих процесів.","Кейс PlanFix є історичною практикою; доступи й сценарії перевіряють у цільовому акаунті перед реалізацією."],"problems":["керівник забуває обіцяний перегляд зарплати","як не пропустити індивідуальну дату перегляду оплати","працівник чекає рішення про зарплату"],"synonyms":["ревізія окладу","перегляд зарплатної політики","обіцяне підвищення","індивідуальний перегляд винагороди"],"search_queries":["як не забути обіцяний працівнику перегляд зарплати","як нагадати керівнику про дату перегляду оплати","як зафіксувати рішення залишити зарплату до наступного перегляду"],"sources":[{"type":"public_case","title":"PlanFix: облік зарплатних політик у Alisa.ua","url":"https://planfix.ru/blog/a-u-vas-kak-organizovat-uchyot-zarplatnyh-politik-v-planfikse/","checked_at":"2026-10-09","supports":"Кейс від 26.11.2020 описує індивідуальні політики, зв’язок із контактом працівника, доступ керівника до підлеглих, нагадування про прострочення та погодження з CEO. Автор прямо зазначає, що щомісячний розрахунок зарплати не автоматизовано."},{"type":"inferred_pattern","title":"Редакційна модель завершення індивідуального перегляду","supports":"Контроль повторів, рішення залишити умови або перенести перегляд, підтвердження повідомлення, передавання кадрової зміни та оцінки годин є гіпотезами для аудиту. Це не підтверджений кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"compensation-review-reminder","title":"Нагадування та рішення власника","description":"Індивідуальні дати й прострочення ведуть у задачах; власник фіксує рішення та наступний перегляд.","best_for":["Невелика команда з одним погоджувачем і ручним внесенням дат."],"example":"Після випробувального строку керівник обіцяв обговорити оплату в грудні. Нагадування повернуло домовленість у його чергу; він залишив умови, пояснив рішення працівнику й визначив наступний перегляд у березні.","implementation_methods":["Налаштувати шаблон задачі з працівником, строком, відповідальним і рішенням.","Показати прострочення у фільтрі та налаштувати нагадування.","Зберігати дату наступного перегляду й посилання на попередню домовленість."],"complexity":"low","hours_min":10,"hours_max":20,"requirements":["Власник вручну підтверджує рішення й наступну дату."],"limitations":["Автоматичний імпорт кадрових даних і командне бюджетування не включені."],"pricing_modifiers":[]},{"id":"compensation-review-managed","title":"Перегляд із погодженням та ескалацією","description":"Керівник готує обґрунтування, погоджувач ухвалює рішення, а прострочення й повернення контролюються окремими статусами.","best_for":["Команда з кадровим координатором і розмежуванням доступу між керівниками."],"example":"Координатор отримав прострочений перегляд після зміни керівника. Він передав відповідальність новому керівнику, перевірив доступ, а власник повернув неповне обґрунтування. Після погодження зміни створили пов’язану кадрову задачу.","implementation_methods":["Налаштувати статуси підготовки, погодження, повернення й завершення з фіксацією автора рішення.","Ескалувати прострочення координатору та зберігати історію зміни відповідального.","Передавати погоджену зміну в кадровий процес і пов’язувати її з переглядом."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Визначено координатора, матрицю доступу та правила повернення на доопрацювання."],"limitations":["Рішення ухвалює людина; автоматичний розрахунок ринкової ставки не включений."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0140","reason":"Після рішення змінити оплату AUT-0140 вводить погоджені умови з датою чинності. Ця картка контролює своєчасність самого перегляду, включно з рішенням залишити умови."},{"type":"related","target_id":"AUT-0224","reason":"AUT-0224 погоджує сукупний бюджет командного циклу. Індивідуальна обіцяна дата може настати поза таким циклом; ця картка не розподіляє командний бюджет."}],"configurator_questions":[{"id":"compensation-review-management-changes","question":"Чи потрібно передавати відкриті перегляди після зміни керівника?","help_text":"Визначте джерело підпорядкування та хто підтверджує нові права доступу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Додати передачу відповідальності та перевірку доступу до відкритих переглядів."}]},{"id":"compensation-review-hr-import","question":"Чи потрібно імпортувати індивідуальні дати з кадрової системи?","help_text":"Потрібні стабільні ID працівників і правило обробки змінених чи видалених домовленостей.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Додати зіставлення працівників, контроль повторного імпорту та конфліктів дат."}]}]},{"schema_version":1,"id":"AUT-0469","slug":"asset-value-adjustment-reconciliation","title":"Звірка погодженого коригування вартості основного засобу","summary":"Погоджену оцінку звіряють із проведенням, карткою активу та оновленим графіком амортизації.","problem":"Фінансист погодив нову вартість обладнання, але її змінили лише в таблиці або застосували до іншої облікової моделі. Реєстр активів і бухгалтерські записи показують різні суми.","outcome":"Коригування має підтверджену підставу, дату, облікову модель і проведення; вартість активу та майбутній графік відповідають погодженому рішенню.","category":"finance","subcategory":"reporting","roles":["finance-specialist","operations-manager"],"industries":["manufacturing","cross-industry"],"triggers":["Уповноважений фінансист погодив окрему зміну балансової вартості чинного основного засобу."],"workflow_steps":["Зафіксувати актив, облікову модель, дату чинності та підставу оцінки; зберегти поточну вартість і вже проведену амортизацію.","Передати оцінку фінансисту для підтвердження суми, рахунка різниці та центру витрат; повернути неповну підставу на уточнення.","Перед виконанням перевірити, чи не змінились актив і його графік після погодження; за зміни вихідних даних запросити повторний розгляд.","Отримати ID виконаного коригування від облікової системи; невизначену відповідь передати відповідальному без повторного проведення.","Зіставити нову вартість, суму різниці й дату в картці активу та проведенні; перевірити графік наступних періодів.","Закрити лише звірене коригування; незбіг рахунка або моделі оформити як окреме виправлення зі збереженням історії."],"requirements":["Є погоджена оцінка, стабільний ID активу та визначена облікова модель.","Фінансист затверджує рахунок різниці й порядок виправлень."],"limitations":["Автоматизація не визначає справедливу вартість і не обирає облікову політику.","Фізичне вибуття, первинна капіталізація та планова амортизація мають окремі процеси.","Модель реалізації та години є попередніми; можливості й доступи PlanFix перевіряють перед впровадженням."],"problems":["Фінансист погодив нову вартість обладнання, але її змінили лише в таблиці або застосували до іншої облікової моделі. Реєстр активів і бухгалтерські записи показують різні суми."],"synonyms":["коригування балансової вартості","оцінка основного засобу","зміна вартості активу"],"search_queries":["як звірити нову вартість обладнання після погодженої оцінки","як перевірити графік амортизації після коригування вартості активу"],"sources":[{"type":"vendor_documentation","title":"ERPNext: Asset Value Adjustment","url":"https://docs.frappe.io/erpnext/asset-value-adjustment","checked_at":"2026-10-09","supports":"Документація описує зміну вартості активу на дату, вибір Finance Book, рахунок різниці, пов’язане проведення та перевірку майбутнього графіка. Не встановлює політику оцінки клієнта."},{"type":"inferred_pattern","title":"Редакційна модель контролю погодженого результату","supports":"Маршрут погодження, контроль повторів, приклади, запитання, ескалація та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS або функції PlanFix."}],"status":"draft","variants":[{"id":"asset-value-adjustment-reconciliation-tracked","title":"Контроль із підтвердженням результату","description":"Погоджену оцінку звіряють із проведенням, карткою активу та оновленим графіком амортизації.","best_for":["Команда має облікове джерело та відповідального фінансиста; потрібен контроль виконання погодженого рішення."],"example":"Погоджено зменшення вартості верстата із 36000 до 28000 в управлінській моделі. Проведення змінило іншу модель. Звірка залишила коригування відкритим до виправлення; первинний запис зберегли.","implementation_methods":["Створити картку коригування з доказом оцінки, вихідним станом та рішенням фінансиста.","Отримувати стан проведення й графіка з обліку та показувати незбіжні активи в черзі фінансиста."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є погоджена оцінка, стабільний ID активу та визначена облікова модель.","Фінансист затверджує рахунок різниці й порядок виправлень."],"limitations":["Автоматизація не визначає справедливу вартість і не обирає облікову політику.","Фізичне вибуття, первинна капіталізація та планова амортизація мають окремі процеси."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0118","reason":"AUT-0118 перевіряє виконання планових нарахувань; ця картка звіряє окреме погоджене коригування вартості та його вплив на майбутній графік."},{"type":"related","target_id":"AUT-0117","reason":"Первинне збирання витрат формує вартість нового активу. Тут змінюється оцінка вже облікованого активу."}],"configurator_questions":[{"id":"asset-value-adjustment-reconciliation-books","question":"Чи потрібно перевіряти кілька облікових моделей окремо?","help_text":"Визначте моделі та забороніть сумування їх оцінок між собою.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Визначте моделі та забороніть сумування їх оцінок між собою."}]},{"id":"asset-value-adjustment-reconciliation-connector","question":"Чи потрібне автоматичне читання проведення й графіка з обліку?","help_text":"Потрібні стабільні ID та доступ лише до необхідних даних; запис проведень не включено.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Потрібні стабільні ID та доступ лише до необхідних даних; запис проведень не включено."}]}]},{"schema_version":1,"id":"AUT-0470","slug":"backdated-stock-valuation-repost-control","title":"Контроль перерахунку складської оцінки після операції минулою датою","summary":"Команда контролює межі та завершення фонового перерахунку складських рухів і звіряє його вплив на облік.","problem":"Поставку внесли минулою датою, але наступні складські рухи ще мають стару оцінку. Запуск фонового перерахунку помилково вважають його завершенням і випускають непогоджений звіт.","outcome":"Кожний перерахунок має погоджений часовий зріз, перелік товарів і складів, стан виконання та звірку складської й бухгалтерської вартості.","category":"inventory","subcategory":"stock-control","roles":["finance-specialist","operations-manager"],"industries":["wholesale","manufacturing","retail"],"triggers":["Облікова система поставила перерахунок оцінки в чергу після створення або виправлення складського руху минулою датою."],"workflow_steps":["Пов’язати перерахунок із первинним рухом, компанією, товаром, складом і найранішою зачепленою датою; зберегти вихідні підсумки.","Перевірити допустимість зміни історичного періоду з фінансистом; закритий період передати на окремий розгляд.","Визначити обмежену область перерахунку й відповідального; виявити вже активні завдання для тієї самої області.","Відстежувати ID фонового завдання та його кінцевий стан; помилку або зависання передати технічному відповідальному без запуску іншого завдання навмання.","Після завершення звірити складські підсумки й пов’язані облікові записи за однаковим зрізом; розбіжності залишити відкритими.","Зберегти результат і вплив на звіти; повідомити їх власників про потребу оновлення лише після підтвердженої звірки."],"requirements":["Система надає ID, межі та стан завдання перерахунку.","Є погоджений порядок роботи з історичними періодами й доступ до обох регістрів."],"limitations":["Перерахунок виконує облікова система; каталог не пропонує переписування її регістрів.","Процес не замінює фізичну інвентаризацію чи рішення про нову оцінку запасу.","Модель реалізації та години є попередніми; можливості й доступи PlanFix перевіряють перед впровадженням."],"problems":["Поставку внесли минулою датою, але наступні складські рухи ще мають стару оцінку. Запуск фонового перерахунку помилково вважають його завершенням і випускають непогоджений звіт."],"synonyms":["перепроведення складської оцінки","перерахунок собівартості заднім числом","фоновий перерахунок запасу"],"search_queries":["як перевірити завершення перерахунку складу після поставки минулою датою","як контролювати фоновий перерахунок собівартості складських рухів"],"sources":[{"type":"vendor_documentation","title":"ERPNext: Repost Item Valuation","url":"https://docs.frappe.io/erpnext/repost-item-valuation","checked_at":"2026-10-09","supports":"Описано перерахунок складських і пов’язаних бухгалтерських значень після рухів минулою датою, фонову чергу та обмеження області. Документація застерігає щодо закритих років і навантаження."},{"type":"inferred_pattern","title":"Редакційна модель контролю погодженого результату","supports":"Маршрут погодження, контроль повторів, приклади, запитання, ескалація та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS або функції PlanFix."}],"status":"draft","variants":[{"id":"backdated-stock-valuation-repost-control-tracked","title":"Контроль із підтвердженням результату","description":"Команда контролює межі та завершення фонового перерахунку складських рухів і звіряє його вплив на облік.","best_for":["Команда має облікове джерело та відповідального фінансиста; потрібен контроль виконання погодженого рішення."],"example":"Приймання за понеділок внесли в п’ятницю після продажів. Завдання залишилось у черзі. Координатор не підтвердив звіт про маржу, доки облік не завершив перерахунок і фінансист не звірив зачеплені рухи.","implementation_methods":["Вести завдання перерахунку з областю, станом і відповідальним; нагадувати про незавершену звірку.","Читати стан фонового завдання та підсумки обох регістрів через дозволений інтерфейс обліку."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Система надає ID, межі та стан завдання перерахунку.","Є погоджений порядок роботи з історичними періодами й доступ до обох регістрів."],"limitations":["Перерахунок виконує облікова система; каталог не пропонує переписування її регістрів.","Процес не замінює фізичну інвентаризацію чи рішення про нову оцінку запасу."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0191","reason":"AUT-0191 погоджує нову оцінку запасу без зміни кількості. Тут перевіряється перерахунок ланцюга історичних рухів після зміни первинної операції."},{"type":"related","target_id":"AUT-0432","reason":"Звірений перерахунок може бути умовою готовності управлінського звіту; ця картка контролює конкретне фонове завдання обліку."}],"configurator_questions":[{"id":"backdated-stock-valuation-repost-control-jobs","question":"Чи потрібно автоматично читати стан фонових завдань?","help_text":"Укажіть систему, кінцеві стани й допустимий час виконання.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Укажіть систему, кінцеві стани й допустимий час виконання."}]},{"id":"backdated-stock-valuation-repost-control-reports","question":"Чи потрібно пов’язувати перерахунок із кількома залежними звітами?","help_text":"Визначте власників звітів і зачеплений часовий зріз.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Визначте власників звітів і зачеплений часовий зріз."}]}]},{"schema_version":1,"id":"AUT-0471","slug":"loan-restructured-schedule-activation","title":"Звірка нового графіка після погодженої реструктуризації позики","summary":"Погоджені нові умови зіставляють із чинним графіком, залишком і правилами перенесення нарахованих сум.","problem":"Сторони погодили новий строк позики, але облік і нагадування продовжують старий графік. Нараховані відсотки включили в борг двічі або втратили під час заміни умов.","outcome":"Реструктуризація має підтверджене рішення, дату чинності й звірений новий графік; попередні умови збережені, майбутні нагадування використовують чинну редакцію.","category":"finance","subcategory":"payments","roles":["finance-specialist","operations-manager"],"industries":["cross-industry"],"triggers":["Уповноважені сторони підтвердили зміну умов чинної позики та дату її введення."],"workflow_steps":["Пов’язати зміну з договором, рішенням сторін і датою чинності; зафіксувати залишок тіла, відсотки та інші нарахування на погоджений момент.","Зберегти новий строк, ставку, дату першої оплати й окреме рішення щодо кожної нарахованої складової.","Порівняти запропонований графік із підтвердженими умовами; незбіжну суму або пропущену складову повернути фінансисту.","Отримати підтвердження введення графіка в джерелі обліку; платіж між погодженням і введенням передати на повторну звірку.","Перевірити чинну редакцію та майбутні нагадування; виключити паралельні повідомлення за скасованими майбутніми рядками старого графіка.","Зберегти попередній графік, рішення й результат; першу оплату за новими умовами контролювати як окреме фактичне виконання."],"requirements":["Є підтверджена домовленість сторін, дата чинності та відповідальний фінансист.","Система розділяє залишок тіла, відсотки, збори та редакції графіка."],"limitations":["Процес не ухвалює кредитне рішення й не визначає правомірність нових умов.","Не списує борг і не вважає новий графік доказом фактичного погашення.","Модель реалізації та години є попередніми; можливості й доступи PlanFix перевіряють перед впровадженням."],"problems":["Сторони погодили новий строк позики, але облік і нагадування продовжують старий графік. Нараховані відсотки включили в борг двічі або втратили під час заміни умов."],"synonyms":["зміна графіка погашення","реструктуризація позики","перенесення нарахованих відсотків"],"search_queries":["як перевірити новий графік позики після реструктуризації","як прибрати старі нагадування після погодженої зміни строку позики"],"sources":[{"type":"vendor_documentation","title":"Frappe Lending: Loan Restructure","url":"https://docs.frappe.io/lending/loan-restructure","checked_at":"2026-10-09","supports":"Описано зміну умов чинної позики, дату реструктуризації, новий строк і ставку, обробку нарахованих відсотків та зборів і перевірку нового графіка перед підтвердженням."},{"type":"inferred_pattern","title":"Редакційна модель контролю погодженого результату","supports":"Маршрут погодження, контроль повторів, приклади, запитання, ескалація та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS або функції PlanFix."}],"status":"draft","variants":[{"id":"loan-restructured-schedule-activation-tracked","title":"Контроль із підтвердженням результату","description":"Погоджені нові умови зіставляють із чинним графіком, залишком і правилами перенесення нарахованих сум.","best_for":["Команда має облікове джерело та відповідального фінансиста; потрібен контроль виконання погодженого рішення."],"example":"Сторони підтвердили довший строк і перенесення погоджених відсотків у першу оплату. Перевірка знайшла ті самі відсотки також у тілі боргу. Фінансист виправив проєкт до введення нового графіка.","implementation_methods":["Вести зміну умов як окремий запис із редакціями графіка й рішеннями щодо складових боргу.","Читати чинний графік з обліку, звіряти його з рішенням і керувати нагадуваннями за редакцією."],"complexity":"medium","hours_min":24,"hours_max":48,"requirements":["Є підтверджена домовленість сторін, дата чинності та відповідальний фінансист.","Система розділяє залишок тіла, відсотки, збори та редакції графіка."],"limitations":["Процес не ухвалює кредитне рішення й не визначає правомірність нових умов.","Не списує борг і не вважає новий графік доказом фактичного погашення."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0252","reason":"AUT-0252 контролює дотримання договірних показників; тут звіряється введення вже погодженого нового графіка."},{"type":"related","target_id":"AUT-0166","reason":"Контроль фактичного повернення позики може використати новий графік. Ця картка перевіряє зміну умов, а не погашення."}],"configurator_questions":[{"id":"loan-restructured-schedule-activation-schedule","question":"Чи потрібне автоматичне читання графіка та залишків з обліку?","help_text":"Визначте ID позики, редакцію графіка та обробку оплат між перевірками.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Визначте ID позики, редакцію графіка та обробку оплат між перевірками."}]},{"id":"loan-restructured-schedule-activation-notifications","question":"Чи потрібно замінювати майбутні нагадування в зовнішній системі?","help_text":"Потрібні ID повідомлень і перевірка чинної редакції перед відправленням.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Потрібні ID повідомлень і перевірка чинної редакції перед відправленням."}]}]},{"schema_version":1,"id":"AUT-0472","slug":"course-next-cohort-reset-readiness","title":"Підготовка навчального курсу до нового потоку","summary":"Перед новим потоком координатор перевіряє архів результатів, погоджений склад очищення та нові дати курсу.","problem":"Новий потік бачить роботи й оцінки попереднього або має старі строки завдань. Поспішне очищення стирає потрібні результати без доступного архіву.","outcome":"Курс має погоджений архів попереднього потоку, перевірені нові дати та чисті потрібні активності; результати попередніх слухачів доступні лише уповноваженим особам.","category":"project-operations","subcategory":"task-management","roles":["operations-manager","project-manager"],"industries":["education"],"triggers":["Координатор готує повторне використання чинного курсу для наступного навчального потоку."],"workflow_steps":["Зафіксувати курс, завершений і наступний потоки, потрібні дані архіву та відповідального.","Підготувати резервну копію з потрібними результатами й перевірити її доступність; погодити конкретні категорії очищення.","Уповноважений адміністратор виконує погоджене очищення; незавершені роботи й потрібну історію зберігає за окремим рішенням.","Перевірити нову дату початку та строки активностей; звірити склад груп, оцінки й дані робіт після виконання.","Перевірити курс з роллю нового слухача; координатор підтверджує готовність або повертає конкретні розбіжності на виправлення."],"requirements":["Є відповідальний за курс, правила архівування та адміністратор із належними правами.","Визначено склад очищення, нову дату й перелік активностей для перевірки."],"limitations":["Очищення виконує уповноважена людина; наявність файлу резервної копії сама по собі не доводить можливість відновлення.","Процес не видаляє всі журнали платформи й не замінює політику зберігання даних.","Можливості та права конкретної системи перевіряють перед реалізацією; години є попередніми."],"problems":["Новий потік бачить роботи й оцінки попереднього або має старі строки завдань. Поспішне очищення стирає потрібні результати без доступного архіву."],"synonyms":["очищення курсу","новий навчальний потік","повторне використання курсу"],"search_queries":["як підготувати навчальний курс до нового потоку без старих оцінок"],"sources":[{"type":"vendor_documentation","title":"Moodle 4.5: Reset course","url":"https://docs.moodle.org/405/en/Reset_course","checked_at":"2026-10-09","supports":"Документація описує вибіркове очищення даних курсу, резервну копію перед незворотною дією та перенесення дат. Не підтверджує універсальне видалення журналів."},{"type":"inferred_pattern","title":"Редакційна модель контролю конкретного процесу","supports":"Маршрут перевірки й погодження, приклад, контроль повторів, запитання та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS чи функції PlanFix."}],"status":"draft","variants":[{"id":"course-next-cohort-reset-readiness-tracked","title":"Контроль із перевіркою фактичного результату","description":"Перед новим потоком координатор перевіряє архів результатів, погоджений склад очищення та нові дати курсу.","best_for":["Навчальна команда має LMS і координатора відповідного процесу."],"example":"Курс відкривають для жовтневого потоку. Координатор знайшов відкриті роботи вересневих слухачів і відокремив їх до очищення. Новий слухач бачить свої строки та не бачить попередніх робіт.","implementation_methods":["Вести checklist підготовки потоку з доказом архіву, погодженням очищення та перевіркою дат.","Зберігати результати перевірки навчальної платформи й передавати незбіжні активності адміністратору."],"complexity":"medium","hours_min":14,"hours_max":28,"requirements":["Є відповідальний за курс, правила архівування та адміністратор із належними правами.","Визначено склад очищення, нову дату й перелік активностей для перевірки."],"limitations":["Очищення виконує уповноважена людина; наявність файлу резервної копії сама по собі не доводить можливість відновлення.","Процес не видаляє всі журнали платформи й не замінює політику зберігання даних."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0113","reason":"Контроль завершення навчання перевіряє результати окремого працівника. Тут готують повторне використання курсу для нового потоку."},{"type":"related","target_id":"AUT-0197","reason":"Рішення щодо строку зберігання задає правила архіву; ця картка перевіряє конкретний курс перед новим запуском."}],"configurator_questions":[{"id":"course-next-cohort-reset-readiness-archive","question":"Чи потрібна контрольна перевірка відновлення архіву в окремому контурі?","help_text":"Погодьте склад даних і доступ до окремого навчального середовища.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Погодьте склад даних і доступ до окремого навчального середовища."}]},{"id":"course-next-cohort-reset-readiness-dates","question":"Чи потрібно перевіряти строки різних типів активностей?","help_text":"Складіть перелік тестів, робіт і календарних подій; не всі розширення обробляють дати однаково.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Складіть перелік тестів, робіт і календарних подій; не всі розширення обробляють дати однаково."}]}]},{"schema_version":1,"id":"AUT-0473","slug":"cohort-course-enrolment-reconciliation","title":"Звірка зарахування навчального потоку на потрібні курси","summary":"Зміни складу навчального потоку звіряють із фактичним зарахуванням на погоджені курси та окремими винятками.","problem":"Слухача додали до потоку, але потрібні курси не відкрились. Після вилучення слухача доступ лишився через інший спосіб зарахування.","outcome":"Кожний слухач має перевірений стан зарахування за курсом і методом; пропуски та додаткові підстави доступу передані координатору.","category":"customer-service","subcategory":"service-delivery","roles":["operations-manager"],"industries":["education"],"triggers":["Змінився склад навчального потоку або перелік курсів, пов’язаних із ним."],"workflow_steps":["Зафіксувати ID потоку, курси, чинний склад і джерело змін; визначити відповідального за винятки.","Перевірити наявність дозволеного зв’язку потоку з кожним курсом та область видимості потоку.","Зіставити очікуваний склад із фактичним зарахуванням за конкретним методом; відокремити ручні й інші підстави доступу.","Пропущене зарахування чи невдалу зміну передати адміністратору; іншу чинну підставу доступу не скасовувати без рішення.","Після виправлення звірити стан повторно, повідомити координатора та зберегти журнал змін складу."],"requirements":["Потоки й слухачі мають стабільні ID; визначено відповідність потоку та курсів.","Навчальна система надає відомості про методи зарахування."],"limitations":["Членство в потоці не доводить завершення курсу.","Вилучення одного методу не гарантує припинення доступу через інші методи; оплату й права перевіряють окремо.","Можливості та права конкретної системи перевіряють перед реалізацією; години є попередніми."],"problems":["Слухача додали до потоку, але потрібні курси не відкрились. Після вилучення слухача доступ лишився через інший спосіб зарахування."],"synonyms":["зарахування когорти","синхронізація навчального потоку","слухач не бачить курс"],"search_queries":["як перевірити зарахування всіх слухачів потоку на потрібні курси"],"sources":[{"type":"vendor_documentation","title":"Moodle 4.5: Cohort sync","url":"https://docs.moodle.org/405/en/Cohort_sync","checked_at":"2026-10-09","supports":"Документація описує зарахування та вилучення за членством у когорті, доступність когорти на рівні сайту чи категорії та можливість зв’язку з групою."},{"type":"inferred_pattern","title":"Редакційна модель контролю конкретного процесу","supports":"Маршрут перевірки й погодження, приклад, контроль повторів, запитання та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS чи функції PlanFix."}],"status":"draft","variants":[{"id":"cohort-course-enrolment-reconciliation-tracked","title":"Контроль із перевіркою фактичного результату","description":"Зміни складу навчального потоку звіряють із фактичним зарахуванням на погоджені курси та окремими винятками.","best_for":["Навчальна команда має LMS і координатора відповідного процесу."],"example":"Із потоку прибрали слухача. Зарахування через потік зникло, але ручний запис залишився. Координатор перевірив його підставу; система не оголосила доступ припиненим лише за зміною когорти.","implementation_methods":["Налаштувати реєстр потоків і курсів з чергою пропущених зарахувань.","Читати методи зарахування з навчальної системи та зіставляти їх із погодженим складом."],"complexity":"medium","hours_min":16,"hours_max":32,"requirements":["Потоки й слухачі мають стабільні ID; визначено відповідність потоку та курсів.","Навчальна система надає відомості про методи зарахування."],"limitations":["Членство в потоці не доводить завершення курсу.","Вилучення одного методу не гарантує припинення доступу через інші методи; оплату й права перевіряють окремо."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0113","reason":"Завершення навчання використовує підтверджений доступ, але не звіряє зарахування всього потоку."},{"type":"related","target_id":"AUT-0475","reason":"Потік визначає зарахування на курс; навчальні групи визначають склад роботи в конкретних активностях."}],"configurator_questions":[{"id":"cohort-course-enrolment-reconciliation-source","question":"Чи потрібно читати склад потоку із зовнішнього реєстру слухачів?","help_text":"Визначте стабільний ключ слухача та правила вилучення з потоку.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Визначте стабільний ключ слухача та правила вилучення з потоку."}]},{"id":"cohort-course-enrolment-reconciliation-methods","question":"Чи потрібно розбирати одночасні ручні та автоматичні методи зарахування?","help_text":"Укажіть пріоритети й власника рішення для додаткової підстави доступу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Укажіть пріоритети й власника рішення для додаткової підстави доступу."}]}]},{"schema_version":1,"id":"AUT-0474","slug":"external-grade-import-reconciliation","title":"Звірка імпорту зовнішніх оцінок у журнал курсу","summary":"Координатор перевіряє відповідність слухачів, колонок і шкал до перенесення вже затверджених оцінок та звіряє результат.","problem":"Файл оцінок завантажили за іменами слухачів або неправильно зіставили колонки. Новий імпорт перезаписав актуальніші оцінки чи коментарі.","outcome":"Кожна імпортована оцінка пов’язана з правильним слухачем і елементом журналу; конфлікти редакцій розглянуті, результат зіставлений із затвердженим файлом.","category":"customer-service","subcategory":"quality","roles":["operations-manager"],"industries":["education"],"triggers":["Отримано затверджений файл результатів для внесення в чинний журнал курсу."],"workflow_steps":["Зафіксувати курс, версію файлу, дату оцінювання та власника затверджених результатів; зберегти вихідний журнал.","Перевірити ID слухачів, елементів оцінювання, шкалу й кодування; неоднозначні відповідності повернути на уточнення.","Показати попередній перегляд зіставлення колонок і вплив на наявні оцінки та відгуки.","Виявити новіші зміни журналу й отримати рішення про конфлікти; примусовий імпорт не виконувати за замовчуванням.","Після дозволеного імпорту прочитати цільові результати та звірити кожний рядок; пропуски й перезаписи залишити у черзі виправлення."],"requirements":["Результати затверджені до імпорту; слухачі та елементи журналу мають ключі.","Визначено шкалу, формат та порядок конфліктів із чинними оцінками."],"limitations":["Імпорт не оцінює роботу й не приймає рішення за апеляцією.","Налаштування журналу можуть змінювати можливість подальшого редагування оцінки в самій активності.","Можливості та права конкретної системи перевіряють перед реалізацією; години є попередніми."],"problems":["Файл оцінок завантажили за іменами слухачів або неправильно зіставили колонки. Новий імпорт перезаписав актуальніші оцінки чи коментарі."],"synonyms":["імпорт оцінок CSV","зіставлення оцінок","оцінки з таблиці"],"search_queries":["як звірити оцінки з файлу після імпорту в журнал курсу"],"sources":[{"type":"vendor_documentation","title":"Moodle 4.5: Grade import","url":"https://docs.moodle.org/405/en/Grade_import","checked_at":"2026-10-09","supports":"Описано CSV/XML імпорт, ключі слухачів і елементів, попереднє зіставлення, ручне перевизначення та ризик перезаписування оцінок під час імпорту відгуків."},{"type":"inferred_pattern","title":"Редакційна модель контролю конкретного процесу","supports":"Маршрут перевірки й погодження, приклад, контроль повторів, запитання та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS чи функції PlanFix."}],"status":"draft","variants":[{"id":"external-grade-import-reconciliation-tracked","title":"Контроль із перевіркою фактичного результату","description":"Координатор перевіряє відповідність слухачів, колонок і шкал до перенесення вже затверджених оцінок та звіряє результат.","best_for":["Навчальна команда має LMS і координатора відповідного процесу."],"example":"У файлі два слухачі з однаковим прізвищем. Координатор використав їх ID. Для одного результату журнал уже містив новіше виправлення; цей рядок розглянули до завантаження.","implementation_methods":["Створити контрольний пакет імпорту з файлом, mapping і рішеннями щодо конфліктів.","Читати збережені результати журналу для порівняння зі схваленими рядками."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Результати затверджені до імпорту; слухачі та елементи журналу мають ключі.","Визначено шкалу, формат та порядок конфліктів із чинними оцінками."],"limitations":["Імпорт не оцінює роботу й не приймає рішення за апеляцією.","Налаштування журналу можуть змінювати можливість подальшого редагування оцінки в самій активності."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0355","reason":"AUT-0355 оцінює здану роботу й дозволяє публікацію. Тут переносяться вже затверджені зовнішні оцінки з контролем ключів і перезапису."},{"type":"related","target_id":"AUT-0284","reason":"Оскарження оцінки змінює її за рішенням; імпорт має врахувати новішу редакцію, а не переглядати результат іспиту."}],"configurator_questions":[{"id":"external-grade-import-reconciliation-scales","question":"Чи потрібно зіставляти кілька погоджених шкал оцінювання?","help_text":"Погодьте відповідність значень, межі та округлення з відповідальним викладачем.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Погодьте відповідність значень, межі та округлення з відповідальним викладачем."}]},{"id":"external-grade-import-reconciliation-connector","question":"Чи потрібне автоматичне читання журналу після імпорту?","help_text":"Укажіть інтерфейс LMS, ID курсу та права на потрібні результати.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Укажіть інтерфейс LMS, ID курсу та права на потрібні результати."}]}]},{"schema_version":1,"id":"AUT-0475","slug":"course-activity-group-allocation","title":"Розподіл слухачів на групи для навчальних активностей","summary":"Склад груп звіряють із зарахованими слухачами й правилами конкретних активностей перед початком спільної роботи.","problem":"Слухач зарахований на курс, але не має групи для спільного завдання. Інший слухач потрапив у кілька несумісних груп або бачить чужі обговорення.","outcome":"Для кожної потрібної активності є погоджений склад груп, відповідальний викладач і перевірений режим видимості; незараховані слухачі та непокриті учасники виділені.","category":"project-operations","subcategory":"capacity","roles":["operations-manager","project-manager"],"industries":["education"],"triggers":["Погоджено склад курсу та правила поділу слухачів для групової активності."],"workflow_steps":["Отримати зарахованих слухачів, активності й правила поділу; визначити, де потрібна одна група, а де допустимі кілька.","Підготувати склад із ключами груп та учасників; непокритих або несумісно розподілених слухачів передати координатору.","Викладач погоджує склад і режим окремих чи видимих груп для кожної активності.","Внести дозволений склад у LMS та перевірити зв’язки груп із потрібними активностями; зарахування на курс не підміняти членством у групі.","Перевірити вигляд роботи й обговорень для представників груп; зміни після початку робіт погодити зі збереженням історії участі."],"requirements":["Є погоджені правила поділу й перелік активностей, які підтримують групи.","Групи мають стабільні ключі, а викладач відповідає за видимість робіт."],"limitations":["Група не гарантує участі слухача у роботі чи отримання оцінки.","Підтримку режимів і зміни складу після подання роботи перевіряють для конкретної активності.","Можливості та права конкретної системи перевіряють перед реалізацією; години є попередніми."],"problems":["Слухач зарахований на курс, але не має групи для спільного завдання. Інший слухач потрапив у кілька несумісних груп або бачить чужі обговорення."],"synonyms":["навчальні підгрупи","групові завдання","склад груп курсу"],"search_queries":["як розподілити слухачів курсу на групи для спільних завдань"],"sources":[{"type":"vendor_documentation","title":"Moodle 4.5: Groups","url":"https://docs.moodle.org/405/en/Groups","checked_at":"2026-10-09","supports":"Описано групи на рівні курсу й активності, окремий та видимий режими, склад учасників і унікальний group ID для зіставлення."},{"type":"inferred_pattern","title":"Редакційна модель контролю конкретного процесу","supports":"Маршрут перевірки й погодження, приклад, контроль повторів, запитання та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS чи функції PlanFix."}],"status":"draft","variants":[{"id":"course-activity-group-allocation-tracked","title":"Контроль із перевіркою фактичного результату","description":"Склад груп звіряють із зарахованими слухачами й правилами конкретних активностей перед початком спільної роботи.","best_for":["Навчальна команда має LMS і координатора відповідного процесу."],"example":"У курсі 24 слухачі для шести проєктних груп. Двоє залишилися без групи після пізнього зарахування. Координатор додав їх за погодженим рішенням і перевірив доступ до потрібного обговорення.","implementation_methods":["Вести матрицю слухач–активність–група з перевіркою непокритих учасників.","Зіставляти групові налаштування LMS з погодженим складом і перевіркою видимості."],"complexity":"medium","hours_min":14,"hours_max":28,"requirements":["Є погоджені правила поділу й перелік активностей, які підтримують групи.","Групи мають стабільні ключі, а викладач відповідає за видимість робіт."],"limitations":["Група не гарантує участі слухача у роботі чи отримання оцінки.","Підтримку режимів і зміни складу після подання роботи перевіряють для конкретної активності."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0473","reason":"Зарахування потоку відкриває курс; ця картка формує підгрупи для конкретних робіт."},{"type":"related","target_id":"AUT-0355","reason":"Оцінювання приймає роботи після розподілу; ця картка не визначає оцінки."}],"configurator_questions":[{"id":"course-activity-group-allocation-rules","question":"Чи потрібні різні склади груп для кількох активностей?","help_text":"Укажіть окремі правила й активності; не змішуйте різні склади в одну групу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Укажіть окремі правила й активності; не змішуйте різні склади в одну групу."}]},{"id":"course-activity-group-allocation-changes","question":"Чи потрібно погоджувати зміни груп після початку робіт?","help_text":"Визначте правила перенесення участі й хто дозволяє зміну.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Визначте правила перенесення участі й хто дозволяє зміну."}]}]},{"schema_version":1,"id":"AUT-0476","slug":"peer-review-submission-allocation","title":"Розподіл навчальних робіт для взаємного рецензування","summary":"Здані роботи отримують погоджену кількість рецензентів; куратор бачить пропущені призначення та незавершені рецензії.","problem":"Частина навчальних робіт не отримала рецензентів, а інші перевіряє надто багато слухачів. Перехід до підсумкової оцінки приховує незавершені взаємні перевірки.","outcome":"Кожна робота має перевірені призначення рецензентів і стан виконання; нестачу перевірок вирішено до передачі на підсумкове оцінювання.","category":"customer-service","subcategory":"service-delivery","roles":["operations-manager"],"industries":["education"],"triggers":["Завершився погоджений строк подання робіт для взаємного рецензування."],"workflow_steps":["Зафіксувати здані редакції робіт, доступних рецензентів і правила кількості перевірок.","Погодити участь слухачів без власної роботи, саморецензування та обмеження між групами.","Виконати дозволений ручний або автоматичний розподіл у LMS та прочитати фактичні призначення.","Виявити роботи без потрібних перевіряльників і повторні призначення; куратор погоджує виправлення без прихованого стирання виконаних рецензій.","Нагадати про незавершені рецензії; після строку куратор підтверджує достатність перевірок або призначає додаткову перевірку."],"requirements":["Є критерії рецензії, перелік дозволених рецензентів і власник рішення про достатність.","LMS надає фактичні призначення й стан рецензії."],"limitations":["Наявність рецензії не доводить її якість і не замінює рішення викладача.","Підсумкові оцінки та публікація мають окремий етап.","Можливості та права конкретної системи перевіряють перед реалізацією; години є попередніми."],"problems":["Частина навчальних робіт не отримала рецензентів, а інші перевіряє надто багато слухачів. Перехід до підсумкової оцінки приховує незавершені взаємні перевірки."],"synonyms":["взаємне рецензування","розподіл робіт між слухачами","peer assessment"],"search_queries":["як забезпечити рецензентів для кожної навчальної роботи"],"sources":[{"type":"vendor_documentation","title":"Moodle 4.5: Workshop activity","url":"https://docs.moodle.org/405/en/Workshop_activity","checked_at":"2026-10-09","supports":"Описано взаємне оцінювання, ручний, випадковий і запланований розподіл робіт та перехід між фазами подання, перевірки й підсумкового оцінювання."},{"type":"inferred_pattern","title":"Редакційна модель контролю конкретного процесу","supports":"Маршрут перевірки й погодження, приклад, контроль повторів, запитання та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS чи функції PlanFix."}],"status":"draft","variants":[{"id":"peer-review-submission-allocation-tracked","title":"Контроль із перевіркою фактичного результату","description":"Здані роботи отримують погоджену кількість рецензентів; куратор бачить пропущені призначення та незавершені рецензії.","best_for":["Навчальна команда має LMS і координатора відповідного процесу."],"example":"Для кожної із 18 робіт потрібно дві рецензії. Після розподілу одна робота має лише одного доступного рецензента. Куратор погодив додаткове призначення й перевірив виконання до підсумкового етапу.","implementation_methods":["Вести контроль покриття робіт рецензентами та незавершених рецензій.","Зіставляти фактичні призначення LMS із правилами й передавати винятки куратору."],"complexity":"medium","hours_min":16,"hours_max":32,"requirements":["Є критерії рецензії, перелік дозволених рецензентів і власник рішення про достатність.","LMS надає фактичні призначення й стан рецензії."],"limitations":["Наявність рецензії не доводить її якість і не замінює рішення викладача.","Підсумкові оцінки та публікація мають окремий етап."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0355","reason":"Оцінювання визначає та публікує результат роботи. Тут результат — покриття робіт рецензентами й виконані взаємні перевірки."},{"type":"related","target_id":"AUT-0475","reason":"Склад навчальних груп може обмежувати пари рецензування; розподіл самих груп не призначає конкретні роботи."}],"configurator_questions":[{"id":"peer-review-submission-allocation-groups","question":"Чи потрібні правила рецензування між навчальними групами?","help_text":"Укажіть допустимі пари та обробку недостатньої кількості рецензентів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Укажіть допустимі пари та обробку недостатньої кількості рецензентів."}]},{"id":"peer-review-submission-allocation-sync","question":"Чи потрібно автоматично читати призначення та виконані рецензії?","help_text":"Потрібні ID роботи, рецензента й редакції; доступи перевіряють окремо.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Потрібні ID роботи, рецензента й редакції; доступи перевіряють окремо."}]}]},{"schema_version":1,"id":"AUT-0477","slug":"learning-activity-prerequisite-gate","title":"Перевірка доступу до навчального модуля за передумовами","summary":"Доступність наступного модуля звіряють із потрібними результатами, строками та групою конкретного слухача.","problem":"Наступний модуль відкрився до виконання потрібної роботи або лишився закритим після підтвердженого результату. Координатор вручну відкриває доступ без пояснення причини.","outcome":"Для кожного спірного доступу видно виконані й невиконані передумови; потрібний модуль відкритий за погодженими правилами або має обґрунтований виняток.","category":"customer-service","subcategory":"service-delivery","roles":["operations-manager"],"industries":["education"],"triggers":["Змінився результат попередньої активності, настав строк відкриття або слухач повідомив про заблокований модуль."],"workflow_steps":["Зафіксувати модуль, слухача й чинні правила: дата, результат, завершення активності та група.","Отримати фактичні складові із LMS; відсутній результат не прирівнювати до невдалого проходження.","Зіставити умови з реальною доступністю; суперечність передати куратору з конкретним невиконаним правилом.","Куратор виправляє помилкову умову чи підтверджує окремий виняток із підставою; автоматично знімати всі обмеження не можна.","Після зміни перевірити доступ слухача та дію решти умов; зберегти рішення й пояснення для подальших звернень."],"requirements":["Передумови погоджені викладачем; визначено авторитетне джерело результатів.","Є доступ до правил та можливість перевірити фактичну видимість модуля."],"limitations":["Доступ до модуля не означає завершення навчання або зарахування іншого сертифіката.","Не визначає педагогічну достатність передумов; це рішення відповідального викладача.","Можливості та права конкретної системи перевіряють перед реалізацією; години є попередніми."],"problems":["Наступний модуль відкрився до виконання потрібної роботи або лишився закритим після підтвердженого результату. Координатор вручну відкриває доступ без пояснення причини."],"synonyms":["передумови навчання","послідовне відкриття модулів","умови доступу до завдання"],"search_queries":["як перевірити чому слухачу не відкрився наступний навчальний модуль"],"sources":[{"type":"vendor_documentation","title":"Moodle 4.5: Restrict access","url":"https://docs.moodle.org/405/en/Restrict_access","checked_at":"2026-10-09","supports":"Документація підтверджує умови доступності активностей і розділів за датою, оцінкою, групою та завершенням іншої активності."},{"type":"inferred_pattern","title":"Редакційна модель контролю конкретного процесу","supports":"Маршрут перевірки й погодження, приклад, контроль повторів, запитання та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS чи функції PlanFix."}],"status":"draft","variants":[{"id":"learning-activity-prerequisite-gate-tracked","title":"Контроль із перевіркою фактичного результату","description":"Доступність наступного модуля звіряють із потрібними результатами, строками та групою конкретного слухача.","best_for":["Навчальна команда має LMS і координатора відповідного процесу."],"example":"Слухач здав потрібний тест, але наступний модуль лишився закритим. Перевірка виявила додаткову умову групи після переведення. Куратор виправив групу й перевірив доступ без зняття вимоги тесту.","implementation_methods":["Створити маршрут розгляду заблокованого модуля з переліком передумов і рішенням куратора.","Читати правила й результати LMS для звірки конкретного слухача та активності."],"complexity":"medium","hours_min":14,"hours_max":28,"requirements":["Передумови погоджені викладачем; визначено авторитетне джерело результатів.","Є доступ до правил та можливість перевірити фактичну видимість модуля."],"limitations":["Доступ до модуля не означає завершення навчання або зарахування іншого сертифіката.","Не визначає педагогічну достатність передумов; це рішення відповідального викладача."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0113","reason":"Завершення навчання перевіряє фінальний результат; ця картка перевіряє умови доступності конкретного наступного модуля."},{"type":"related","target_id":"AUT-0285","reason":"Зарахування попереднього навчання потребує рішення про еквівалентність; воно не підміняє фактичні правила доступу до активності."}],"configurator_questions":[{"id":"learning-activity-prerequisite-gate-combined","question":"Чи потрібно перевіряти складені правила з кількома передумовами?","help_text":"Погодьте логіку поєднання дат, результатів і груп для кожного модуля.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Погодьте логіку поєднання дат, результатів і груп для кожного модуля."}]},{"id":"learning-activity-prerequisite-gate-read","question":"Чи потрібно автоматично читати результати й правила навчальної системи?","help_text":"Визначте доступний інтерфейс і права лише на потрібні записи.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Визначте доступний інтерфейс і права лише на потрібні записи."}]}]},{"schema_version":1,"id":"AUT-0478","slug":"share-ownership-transfer-reconciliation","title":"Звірка передавання акцій між чинними власниками","summary":"Погоджене передавання акцій звіряють із реєстром прав, кількістю, діапазоном номерів і залишками обох власників.","problem":"Передавання акцій зафіксували листом, але реєстр містить старого власника або іншу кількість. Реєстрацію зміни помилково вважають доказом оплати угоди.","outcome":"Передавання має підтверджені сторони, кількість, дату й записи реєстру; залишки обох власників звірені, а потрібні облікові записи та оплату відокремлено.","category":"finance","subcategory":"reporting","roles":["finance-specialist","owner"],"industries":["cross-industry"],"triggers":["Уповноважені особи погодили передавання конкретного пакета акцій між власниками."],"workflow_steps":["Пов’язати операцію з рішенням і належними документами; фахівець підтверджує допустимість передавання.","Перевірити ідентичність сторін, чинне володіння, кількість і діапазон номерів за авторитетним реєстром.","Отримати дозвіл на реєстрацію саме погодженого пакета; нові зміни володіння передати на повторну перевірку.","Прочитати запис виконаного передавання та залишки обох сторін; невизначений результат перевірити без повторного руху.","Окремо звірити потрібний бухгалтерський запис та факт оплати за рішенням фінансиста; закрити реєстрову зміну зі збереженням її історії."],"requirements":["Є авторитетний реєстр прав і належні рішення щодо передавання.","Кількість, тип і номери акцій підтверджені уповноваженим фахівцем."],"limitations":["Процес не надає юридичного висновку й не замінює офіційний реєстр.","Випуск нових акцій, викуп компанією та дивіденди не є цим передаванням.","Можливості та права конкретної системи перевіряють перед реалізацією; години є попередніми."],"problems":["Передавання акцій зафіксували листом, але реєстр містить старого власника або іншу кількість. Реєстрацію зміни помилково вважають доказом оплати угоди."],"synonyms":["зміна власника акцій","реєстр акціонерів","передавання пакета акцій"],"search_queries":["як звірити передавання акцій між двома власниками"],"sources":[{"type":"vendor_documentation","title":"ERPNext: Share Transfer","url":"https://docs.frappe.io/erpnext/share-transfer","checked_at":"2026-10-09","supports":"Описано тип Transfer між власниками, діапазон номерів, кількість і зміну залишків. Зміна реєстру відокремлена від створення Journal Entry; юридична допустимість не встановлюється."},{"type":"inferred_pattern","title":"Редакційна модель контролю конкретного процесу","supports":"Маршрут перевірки й погодження, приклад, контроль повторів, запитання та години — гіпотези для аудиту. Джерело не підтверджує впровадження CRMCUSTOMS чи функції PlanFix."}],"status":"draft","variants":[{"id":"share-ownership-transfer-reconciliation-tracked","title":"Контроль із перевіркою фактичного результату","description":"Погоджене передавання акцій звіряють із реєстром прав, кількістю, діапазоном номерів і залишками обох власників.","best_for":["Компанія має погоджене передавання пакета та джерело реєстрових даних."],"example":"Погоджено передавання 1000 акцій: у продавця має залишитися 5000, у покупця — 2000. Реєстр показав правильні залишки; фінансист окремо залишив оплату відкритою до підтвердження банку.","implementation_methods":["Вести погоджене передавання з рішенням, вихідним володінням та доказом реєстрації.","Читати реєстрові залишки й окремо пов’язувати фінансові документи без автоматичного висновку про оплату."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є авторитетний реєстр прав і належні рішення щодо передавання.","Кількість, тип і номери акцій підтверджені уповноваженим фахівцем."],"limitations":["Процес не надає юридичного висновку й не замінює офіційний реєстр.","Випуск нових акцій, викуп компанією та дивіденди не є цим передаванням."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0274","reason":"Дивіденди використовують права на визначену дату, але не змінюють власника пакета. Тут перевіряється конкретна реєстрова зміна."},{"type":"related","target_id":"AUT-0268","reason":"Реалізація опціону має окрему підставу; ця картка контролює передавання вже належного пакета між власниками."}],"configurator_questions":[{"id":"share-ownership-transfer-reconciliation-ranges","question":"Чи потрібно звіряти кілька діапазонів номерів або типів акцій?","help_text":"Погодьте окремі пакети й забороніть подвійне включення номера.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Погодьте окремі пакети й забороніть подвійне включення номера."}]},{"id":"share-ownership-transfer-reconciliation-register","question":"Чи потрібне автоматичне читання реєстру та пов’язаних облікових записів?","help_text":"Укажіть дозволений інтерфейс і авторитетне джерело прав.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Укажіть дозволений інтерфейс і авторитетне джерело прав."}]}]},{"schema_version":1,"id":"AUT-0479","slug":"managed-device-enrolment-readiness","title":"Перевірка готовності пристрою після реєстрації в корпоративному керуванні","summary":"Новий або повторно підготовлений пристрій проходить перевірку реєстрації, потрібних застосунків і політик перед передаванням працівнику.","problem":"Пристрій з’явився в адміністративному списку, але потрібний застосунок не встановився або фаза налаштування користувача зависла. Працівник отримує ноутбук, який ще не готовий до роботи.","outcome":"Пристрій має підтверджену реєстрацію, завершені потрібні фази налаштування та перевірений доступ до робочого сценарію; блокувальні помилки мають власника.","category":"project-operations","subcategory":"task-management","roles":["operations-manager","technician"],"industries":["cross-industry","it-saas"],"triggers":["Новий або підготовлений до повторного використання пристрій почав корпоративну реєстрацію."],"workflow_steps":["Зафіксувати серійний номер, ID пристрою, профіль підготовки та майбутнього користувача; звірити право на видачу.","Отримати стан фаз налаштування пристрою та акаунта; зберегти час останніх діагностичних даних.","Зіставити обов’язкові застосунки й політики з фактичним станом; пропущену фазу не вважати успішно виконаною без перевірки профілю.","Помилку, зависання чи потрібне перезавантаження передати техніку з конкретним блокувальним компонентом.","Після виправлення перевірити потрібний робочий сценарій та рішення про готовність; незавершений пристрій залишити в черзі підготовки."],"requirements":["Є погоджений профіль підготовки, перелік обов’язкових компонентів і ключ пристрою.","Технік має доступ до діагностики фаз та виконує контрольний робочий сценарій."],"limitations":["Запис у системі керування не доводить встановлення всіх застосунків.","Процес не очищує попередні дані та не замінює фізичну видачу майна.","Доступи, ліцензії та підтримку конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Пристрій з’явився в адміністративному списку, але потрібний застосунок не встановився або фаза налаштування користувача зависла. Працівник отримує ноутбук, який ще не готовий до роботи."],"synonyms":["підготовка ноутбука","реєстрація корпоративного пристрою","Enrollment Status Page"],"search_queries":["як перевірити готовність ноутбука після корпоративної реєстрації"],"sources":[{"type":"vendor_documentation","title":"Microsoft: Troubleshoot the Enrollment Status Page","url":"https://learn.microsoft.com/en-us/troubleshoot/mem/intune/device-enrollment/understand-troubleshoot-esp","checked_at":"2026-10-09","supports":"Описано діагностику ESP, фази налаштування, стани потрібних застосунків, можливе пропускання фаз і вимогу перезавантаження."},{"type":"inferred_pattern","title":"Редакційна модель контролю пристрою","supports":"Маршрут задач, звірки, ескалація, приклад, конфігураційні питання й години — гіпотези для аудиту. Джерела Microsoft не підтверджують реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"managed-device-enrolment-readiness-tracked","title":"Контроль із перевіркою стану пристрою","description":"Новий або повторно підготовлений пристрій проходить перевірку реєстрації, потрібних застосунків і політик перед передаванням працівнику.","best_for":["Команда має керовані пристрої, авторитетне джерело станів і відповідального техніка."],"example":"Ноутбук уже є в Intune, але бухгалтерський застосунок лишився в стані помилки. Технік усунув причину, звірив завершення фази й перевірив робочий запуск перед видачею.","implementation_methods":["Створити запис підготовки із серійним номером, профілем, фазами та блокувальними компонентами.","Читати діагностику керування пристроєм і збирати підтвердження готовності техніка."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є погоджений профіль підготовки, перелік обов’язкових компонентів і ключ пристрою.","Технік має доступ до діагностики фаз та виконує контрольний робочий сценарій."],"limitations":["Запис у системі керування не доводить встановлення всіх застосунків.","Процес не очищує попередні дані та не замінює фізичну видачу майна."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0254","reason":"Очищення перед повторним передаванням може передувати підготовці; тут перевіряється нова реєстрація та готовність."},{"type":"related","target_id":"AUT-0055","reason":"Видача майна фіксує відповідального; ця картка перевіряє технічну готовність пристрою."}],"configurator_questions":[{"id":"managed-device-enrolment-readiness-profiles","question":"Чи потрібно перевіряти різні профілі підготовки для кількох ролей?","help_text":"Погодьте окремі списки обов’язкових компонентів для кожної ролі.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Погодьте окремі списки обов’язкових компонентів для кожної ролі."}]},{"id":"managed-device-enrolment-readiness-diagnostics","question":"Чи потрібне автоматичне читання станів із системи керування?","help_text":"Потрібні стабільні ID пристрою та свіжість діагностичних даних.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Потрібні стабільні ID пристрою та свіжість діагностичних даних."}]}]},{"schema_version":1,"id":"AUT-0480","slug":"device-compliance-remediation-followup","title":"Контроль повернення пристрою до вимог корпоративної безпеки","summary":"Невідповідність конкретного пристрою отримує причину, строк і власника; завершення підтверджує свіжий результат перевірки політики.","problem":"Користувачу повідомили про невідповідність пристрою, але її не усунули. Підтримка закриває задачу за відповіддю користувача, хоча політика досі показує помилку або давні дані.","outcome":"Кожна невідповідність має підтверджений стан правила, строк виправлення й рішення щодо подальшого використання пристрою; актуальна перевірка підтверджує відновлення.","category":"security-compliance","subcategory":"audit","roles":["operations-manager","technician"],"industries":["cross-industry","it-saas"],"triggers":["Система керування виявила порушення погодженої політики відповідності пристрою."],"workflow_steps":["Пов’язати пристрій, правило, причину та час перевірки; повторні сповіщення приєднати до відкритої невідповідності.","Показати користувачу дозволені кроки виправлення та погоджений строк; визначити технічного відповідального.","Контролювати нагадування й ескалацію за строком; рішення про обмеження доступу приймає власник політики.","Отримати нову перевірку після виправлення; за відсутності зв’язку чи свіжих даних залишити стан невизначеним.","Підтвердити відповідність конкретному правилу й перевірити застосовані обмеження; інші порушення пристрою лишити відкритими."],"requirements":["Правила, строк і дії погоджені власником безпеки.","Система надає стан конкретної політики та час перевірки."],"limitations":["Повідомлення або самозвіт користувача не доводить відповідності.","Виявлення невідповідності саме по собі не гарантує блокування доступу; потрібен окремо налаштований механізм.","Доступи, ліцензії та підтримку конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Користувачу повідомили про невідповідність пристрою, але її не усунули. Підтримка закриває задачу за відповіддю користувача, хоча політика досі показує помилку або давні дані."],"synonyms":["невідповідний пристрій","політика безпеки ноутбука","відновлення compliance"],"search_queries":["як контролювати усунення невідповідності корпоративного пристрою"],"sources":[{"type":"vendor_documentation","title":"Microsoft Intune: Actions for noncompliance","url":"https://learn.microsoft.com/en-us/intune/device-security/compliance/configure-noncompliance-actions","checked_at":"2026-10-09","supports":"Описано дії за невідповідністю, розклад, повідомлення та окремий зв’язок із Conditional Access. Push не гарантує доставки; додавання до retire list не виконує retire саме по собі."},{"type":"inferred_pattern","title":"Редакційна модель контролю пристрою","supports":"Маршрут задач, звірки, ескалація, приклад, конфігураційні питання й години — гіпотези для аудиту. Джерела Microsoft не підтверджують реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"device-compliance-remediation-followup-tracked","title":"Контроль із перевіркою стану пристрою","description":"Невідповідність конкретного пристрою отримує причину, строк і власника; завершення підтверджує свіжий результат перевірки політики.","best_for":["Команда має керовані пристрої, авторитетне джерело станів і відповідального техніка."],"example":"Ноутбук не відповідає вимозі захисту. Працівник повідомив про виправлення, але останній звіт старий. Координатор залишив задачу відкритою до нового результату й перевірив зняття погодженого обмеження.","implementation_methods":["Вести невідповідність за ключем пристрій–політика з нагадуваннями та чергою прострочень.","Читати актуальні стани відповідності та пов’язувати рішення власника політики з результатом."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Правила, строк і дії погоджені власником безпеки.","Система надає стан конкретної політики та час перевірки."],"limitations":["Повідомлення або самозвіт користувача не доводить відповідності.","Виявлення невідповідності саме по собі не гарантує блокування доступу; потрібен окремо налаштований механізм."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0089","reason":"Вразливість потребує окремої перевірки знахідки; ця картка перевіряє невідповідність стану пристрою політиці без припущення про конкретну вразливість."},{"type":"related","target_id":"AUT-0086","reason":"Перегляд доступів визначає потрібність прав; відповідність пристрою перевіряє технічні умови їх використання."}],"configurator_questions":[{"id":"device-compliance-remediation-followup-rules","question":"Чи потрібні різні строки й ескалації за правилами безпеки?","help_text":"Погодьте їх із власником політики, включно з винятками.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Погодьте їх із власником політики, включно з винятками."}]},{"id":"device-compliance-remediation-followup-sync","question":"Чи потрібне автоматичне читання результатів перевірки пристрою?","help_text":"Укажіть ключ правила, час перевірки та дозволений інтерфейс.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Укажіть ключ правила, час перевірки та дозволений інтерфейс."}]}]},{"schema_version":1,"id":"AUT-0481","slug":"encrypted-drive-helpdesk-recovery","title":"Контроль відновлення доступу до зашифрованого корпоративного диска","summary":"Підтримка перевіряє людину й пристрій, зіставляє ключ відновлення та контролює результат без записування секрету в задачу.","problem":"Працівник бачить екран відновлення шифрування. Підтримка знайшла ключ за схожою назвою ноутбука або передала його без перевірки користувача й не підтвердила наступний захист диска.","outcome":"Право користувача підтверджене; відновлення пов’язане з конкретним диском і ID ключа; доступ та погоджена заміна використаного ключа перевірені без відкритого зберігання секрету.","category":"security-compliance","subcategory":"access","roles":["operations-manager","technician"],"industries":["cross-industry","it-saas"],"triggers":["Уповноважений користувач корпоративного пристрою запросив допомогу на екрані відновлення зашифрованого диска."],"workflow_steps":["Перевірити особу, право на пристрій і корпоративну власність за затвердженою процедурою.","Зафіксувати ID пристрою й ключа з екрана відновлення; зібрати причину переходу в режим відновлення.","Уповноважений адміністратор знаходить потрібний ключ у захищеному джерелі та передає його дозволеним способом; у задачі зберігає лише ідентифікатор і доказ дії.","Отримати підтвердження розблокування саме потрібного диска; апаратну несправність чи підозру на інцидент передати відповідному процесу.","За політикою виконати ротацію використаного ключа та перевірити збереження нової версії; закрити звернення після підтвердження захищеного стану."],"requirements":["Ключі заздалегідь збережені в дозволеному захищеному джерелі.","Є процедура перевірки особи, scoped доступ адміністратора та безпечний канал передавання."],"limitations":["Відсутність потрібного ключа не усувається автоматично; відновлення даних не гарантоване.","Процес не скидає пароль акаунта й не поширює ключ через відкриті коментарі чи повідомлення.","Доступи, ліцензії та підтримку конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Працівник бачить екран відновлення шифрування. Підтримка знайшла ключ за схожою назвою ноутбука або передала його без перевірки користувача й не підтвердила наступний захист диска."],"synonyms":["ключ відновлення диска","BitLocker recovery","заблокований зашифрований диск"],"search_queries":["як контролювати відновлення BitLocker для корпоративного ноутбука"],"sources":[{"type":"vendor_documentation","title":"Microsoft: BitLocker recovery process","url":"https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/recovery-process","checked_at":"2026-10-09","supports":"Описано перевірку користувача й пристрою, зіставлення recovery key ID, захищене отримання та ротацію після відновлення. Резервне збереження ключа потребує налаштування."},{"type":"vendor_documentation","title":"Microsoft Intune: BitLocker key rotation","url":"https://learn.microsoft.com/en-us/intune/device-management/actions/rotate-bitlocker-keys","checked_at":"2026-10-09","supports":"Описано віддалене оновлення ключа OS-диска Windows і потрібні дозволи. Не доводить готовності ключа в конкретному клієнтському акаунті."},{"type":"inferred_pattern","title":"Редакційна модель контролю пристрою","supports":"Маршрут задач, звірки, ескалація, приклад, конфігураційні питання й години — гіпотези для аудиту. Джерела Microsoft не підтверджують реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"encrypted-drive-helpdesk-recovery-tracked","title":"Контроль із перевіркою стану пристрою","description":"Підтримка перевіряє людину й пристрій, зіставляє ключ відновлення та контролює результат без записування секрету в задачу.","best_for":["Команда має керовані пристрої, авторитетне джерело станів і відповідального техніка."],"example":"Після технічного обслуговування ноутбук запросив відновлення. Підтримка перевірила користувача та ID ключа, передала секрет через дозволений канал і зафіксувала успішне розблокування та ротацію без значення ключа в задачі.","implementation_methods":["Вести захищене звернення з перевіркою особи, ID диска, причиною та результатом.","Пов’язати підтвердження адміністратора про відновлення й ротацію з журналом дій захищеного джерела."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Ключі заздалегідь збережені в дозволеному захищеному джерелі.","Є процедура перевірки особи, scoped доступ адміністратора та безпечний канал передавання."],"limitations":["Відсутність потрібного ключа не усувається автоматично; відновлення даних не гарантоване.","Процес не скидає пароль акаунта й не поширює ключ через відкриті коментарі чи повідомлення."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0184","reason":"Відновлення входу працює зі способами автентифікації акаунта; ця картка розблоковує конкретний зашифрований диск."},{"type":"related","target_id":"AUT-0196","reason":"Заміна секрету інтеграції перевіряє споживачів сервісу; recovery key має інший об’єкт і процедуру відновлення пристрою."}],"configurator_questions":[{"id":"encrypted-drive-helpdesk-recovery-stores","question":"Чи потрібні маршрути до кількох дозволених сховищ ключів?","help_text":"Погодьте джерело для кожної групи пристроїв і область доступу адміністратора.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Погодьте джерело для кожної групи пристроїв і область доступу адміністратора."}]},{"id":"encrypted-drive-helpdesk-recovery-rotation","question":"Чи потрібно автоматично звіряти стан ротації після відновлення?","help_text":"Читайте лише метадані стану; значення ключа не передавайте в систему задач.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Читайте лише метадані стану; значення ключа не передавайте в систему задач."}]}]},{"schema_version":1,"id":"AUT-0482","slug":"endpoint-app-installation-reconciliation","title":"Звірка встановлення потрібного застосунку на корпоративних пристроях","summary":"Призначений застосунок звіряють із установленням на кожному потрібному пристрої; помилки, очікування й непридатні платформи розділені.","problem":"Застосунок призначили групі, але частина працівників не отримала його. Загальна кількість призначень приховує помилки, очікування й пристрої з давнім зв’язком.","outcome":"За кожним цільовим пристроєм видно підтверджене встановлення або конкретний виняток; власник знає фактичне покриття потрібним застосунком.","category":"project-operations","subcategory":"task-management","roles":["operations-manager","technician"],"industries":["cross-industry","it-saas"],"triggers":["Погоджений застосунок призначено групі корпоративних пристроїв або настав строк перевірки покриття."],"workflow_steps":["Зафіксувати застосунок, доступну версію, цільові пристрої й тип призначення; погодити критерій необхідного покриття.","Прочитати фактичний стан установки та час останнього зв’язку; відокремити непідтримані й неохоплені пристрої.","Передати техніку помилки, затягнуте очікування та невідповідність очікуваній версії там, де її звітність доступна.","Після виправлення повторно зіставити цільову групу зі станом; зміну складу групи врахувати без прихованого вилучення проблемних пристроїв.","Підтвердити покриття або погоджені винятки й зберегти підсумок; нове призначення саме по собі не закриває помилку."],"requirements":["Є цільова група й перелік пристроїв, що мають отримати застосунок.","Система надає стани установки; доступність версії звірено для типу застосунку."],"limitations":["Призначення ліцензії не доводить встановлення; встановлення не доводить готовності всього робочого процесу.","Для деяких типів застосунків чи некерованих пристроїв детальна звітність недоступна.","Доступи, ліцензії та підтримку конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Застосунок призначили групі, але частина працівників не отримала його. Загальна кількість призначень приховує помилки, очікування й пристрої з давнім зв’язком."],"synonyms":["невдала установка застосунку","покриття пристроїв програмою","App install status"],"search_queries":["як знайти корпоративні пристрої де потрібний застосунок не встановився"],"sources":[{"type":"vendor_documentation","title":"Microsoft Intune: Monitor app assignments","url":"https://learn.microsoft.com/en-us/intune/app-management/monitor-assignments","checked_at":"2026-10-09","supports":"Описано Installed, Not Installed, Failed, Pending, Not Applicable, останній check-in і різну доступність версій та звітів за типом застосунку."},{"type":"inferred_pattern","title":"Редакційна модель контролю пристрою","supports":"Маршрут задач, звірки, ескалація, приклад, конфігураційні питання й години — гіпотези для аудиту. Джерела Microsoft не підтверджують реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"endpoint-app-installation-reconciliation-tracked","title":"Контроль із перевіркою стану пристрою","description":"Призначений застосунок звіряють із установленням на кожному потрібному пристрої; помилки, очікування й непридатні платформи розділені.","best_for":["Команда має керовані пристрої, авторитетне джерело станів і відповідального техніка."],"example":"Застосунок призначено 40 ноутбукам. Звіт показав 35 встановлень, три помилки та два очікування. Технік виправив помилки, а два офлайн-пристрої лишилися відкритими до нового зв’язку.","implementation_methods":["Зіставляти цільову групу зі станами установки за ключем пристрій–застосунок.","Маршрутизувати конкретні коди помилок технікам і зберігати підтверджені результати."],"complexity":"medium","hours_min":16,"hours_max":32,"requirements":["Є цільова група й перелік пристроїв, що мають отримати застосунок.","Система надає стани установки; доступність версії звірено для типу застосунку."],"limitations":["Призначення ліцензії не доводить встановлення; встановлення не доводить готовності всього робочого процесу.","Для деяких типів застосунків чи некерованих пристроїв детальна звітність недоступна."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0170","reason":"Призначення програмної ліцензії не є фактичним встановленням на пристрої."},{"type":"related","target_id":"AUT-0479","reason":"Початкова підготовка перевіряє готовність нового пристрою; ця картка звіряє покриття застосунком діючого парку."}],"configurator_questions":[{"id":"endpoint-app-installation-reconciliation-apps","question":"Чи потрібно звіряти кілька застосунків для різних груп працівників?","help_text":"Погодьте матрицю ролей і потрібних застосунків.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Погодьте матрицю ролей і потрібних застосунків."}]},{"id":"endpoint-app-installation-reconciliation-read","question":"Чи потрібне автоматичне читання звітів установки?","help_text":"Перевірте доступні стани, версії та свіжість для кожного типу застосунку.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Перевірте доступні стани, версії та свіжість для кожного типу застосунку."}]}]},{"schema_version":1,"id":"AUT-0483","slug":"windows-update-device-rollout-gate","title":"Контроль переходу оновлення Windows між групами пристроїв","summary":"Пілотна група підтверджує фактичне оновлення й робочі перевірки до розширення на наступну групу пристроїв.","problem":"Політика оновлення застосувалася, але пристрої ще не встановили потрібне оновлення або не перезавантажились. Команда розширює запуск за успішним станом політики замість стану пристроїв.","outcome":"Перехід між групами має актуальні докази встановлення, перевірки роботи й рішення відповідального; помилки та конфлікти політик розглянуті.","category":"project-operations","subcategory":"task-management","roles":["operations-manager","technician"],"industries":["cross-industry","it-saas"],"triggers":["Погоджене оновлення Windows почало розгортатися в пілотній групі пристроїв."],"workflow_steps":["Зафіксувати цільове оновлення, пілотну та наступні групи, строки й критерії переходу.","Прочитати стан призначення політики окремо від фактичного оновлення; перевірити свіжість даних пристроїв.","Виявити конфлікти налаштувань, помилки, очікування та необхідні перезавантаження; призначити відповідальних за винятки.","Підтвердити встановлення й погоджені робочі перевірки пілотної групи; невідомий стан не включати до успішного покриття.","Власник дозволяє наступну групу або паузу за критеріями; зберегти склад, рішення й повторити контроль для наступного етапу."],"requirements":["Є погоджена схема груп, ціль оновлення й критерії переходу.","Доступні звіти політик і доказ фактичного стану Windows."],"limitations":["Succeeded у звіті політики не дорівнює завершеній установці конкретного оновлення.","Пауза чи повернення залежать від підтримки системи й погодженого маршруту; автоматизація задач не встановлює оновлення.","Доступи, ліцензії та підтримку конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Політика оновлення застосувалася, але пристрої ще не встановили потрібне оновлення або не перезавантажились. Команда розширює запуск за успішним станом політики замість стану пристроїв."],"synonyms":["пілот оновлення Windows","групи оновлення пристроїв","update rings"],"search_queries":["як перевірити пілотне оновлення Windows перед запуском на всіх ноутбуках"],"sources":[{"type":"vendor_documentation","title":"Microsoft Intune: Manage update rings","url":"https://learn.microsoft.com/en-us/intune/device-updates/windows/manage-update-rings","checked_at":"2026-10-09","supports":"Описано групи розгортання, строки, відкладення та перезавантаження. Політики керують поведінкою клієнта."},{"type":"vendor_documentation","title":"Microsoft Intune: Monitor update rings","url":"https://learn.microsoft.com/en-us/intune/device-updates/windows/monitor-update-rings","checked_at":"2026-10-09","supports":"Звіти розділяють призначення й стани налаштувань; Windows Update for Business reports дає окремий погляд на фактичні оновлення."},{"type":"inferred_pattern","title":"Редакційна модель контролю пристрою","supports":"Маршрут задач, звірки, ескалація, приклад, конфігураційні питання й години — гіпотези для аудиту. Джерела Microsoft не підтверджують реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"windows-update-device-rollout-gate-tracked","title":"Контроль із перевіркою стану пристрою","description":"Пілотна група підтверджує фактичне оновлення й робочі перевірки до розширення на наступну групу пристроїв.","best_for":["Команда має керовані пристрої, авторитетне джерело станів і відповідального техніка."],"example":"Політика успішна для 12 пілотних ноутбуків, але три ще чекають перезавантаження. Власник не розширив запуск до перевірки цільового оновлення й робочих застосунків на цих пристроях.","implementation_methods":["Вести етапи розгортання з незмінним складом груп і рішенням про перехід.","Зіставляти звіти політики та фактичного оновлення з перевірками робочого сценарію."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Є погоджена схема груп, ціль оновлення й критерії переходу.","Доступні звіти політик і доказ фактичного стану Windows."],"limitations":["Succeeded у звіті політики не дорівнює завершеній установці конкретного оновлення.","Пауза чи повернення залежать від підтримки системи й погодженого маршруту; автоматизація задач не встановлює оновлення."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0145","reason":"Загальне погодження зміни системи визначає дозвіл і вікно. Тут контролюється поетапне покриття парку пристроїв із розділенням політики й фактичної установки."},{"type":"related","target_id":"AUT-0089","reason":"Виправлення конкретної вразливості може вимагати цього оновлення, але не всі регулярні оновлення починаються зі знахідки."}],"configurator_questions":[{"id":"windows-update-device-rollout-gate-rings","question":"Чи потрібні різні вікна перезавантаження для кількох груп?","help_text":"Погодьте робочі години, строки й правила винятків із власниками команд.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Погодьте робочі години, строки й правила винятків із власниками команд."}]},{"id":"windows-update-device-rollout-gate-reports","question":"Чи потрібне автоматичне читання станів політики та встановлення?","help_text":"Укажіть джерела, ідентифікатори оновлення й часовий зріз.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Укажіть джерела, ідентифікатори оновлення й часовий зріз."}]}]},{"schema_version":1,"id":"AUT-0484","slug":"stale-managed-device-record-review","title":"Перегляд неактивних записів у системі керування пристроями","summary":"Записи з давнім зв’язком перевіряють із відповідальними перед погодженим приховуванням та відстежують їх повернення.","problem":"Неактивні записи спотворюють звіти парку. Їх приховування помилково трактують як очищення фізичного пристрою чи припинення його доступів.","outcome":"Кожний застарілий запис має перевірений життєвий стан і рішення; адміністративне приховування відокремлене від очищення даних, вилучення доступів та вибуття майна.","category":"security-compliance","subcategory":"audit","roles":["operations-manager","technician"],"industries":["cross-industry","it-saas"],"triggers":["Настав перегляд пристроїв, що не виходили на зв’язок довше погодженого строку."],"workflow_steps":["Підготувати список за платформою, ID та останнім зв’язком; зберегти критерій і часовий зріз.","Зіставити записи з фізичним майном і відповідальними; тривале відрядження чи ремонт не називати автоматично вибуттям.","Власник парку погоджує приховування, уточнення або окрему дію життєвого циклу; перед застосуванням перевірити новий зв’язок.","Після виконання звірити журнал прихованих записів із погодженим списком; дані й доступи фізичного пристрою перевіряти окремими процесами.","Повернення запису після нового зв’язку передати на повторний перегляд; зберегти попереднє рішення й стан керування."],"requirements":["Відомі ID, платформи та останній зв’язок; є власник фізичного парку.","Погоджено правила адміністративного приховування й повернення записів."],"limitations":["Приховування Intune не виконує wipe або retire та не видаляє запис Entra ID.","Відсутність зв’язку не доводить втрати чи безпечного очищення; деякі керовані сторонніми засобами пристрої не підтримують ці правила.","Доступи, ліцензії та підтримку конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Неактивні записи спотворюють звіти парку. Їх приховування помилково трактують як очищення фізичного пристрою чи припинення його доступів."],"synonyms":["неактивні пристрої Intune","давній check-in","очищення адміністративного списку"],"search_queries":["як перевірити застарілі записи корпоративних пристроїв перед приховуванням"],"sources":[{"type":"vendor_documentation","title":"Microsoft Intune: Device cleanup rules","url":"https://learn.microsoft.com/en-us/intune/governance/configure-cleanup-rules","checked_at":"2026-10-09","supports":"Правила приховують неактивні записи в порталі й звітах без wipe/retire. Повернення після check-in залежить від чинності сертифіката; запис Entra ID лишається."},{"type":"inferred_pattern","title":"Редакційна модель контролю пристрою","supports":"Маршрут задач, звірки, ескалація, приклад, конфігураційні питання й години — гіпотези для аудиту. Джерела Microsoft не підтверджують реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"stale-managed-device-record-review-tracked","title":"Контроль із перевіркою стану пристрою","description":"Записи з давнім зв’язком перевіряють із відповідальними перед погодженим приховуванням та відстежують їх повернення.","best_for":["Команда має керовані пристрої, авторитетне джерело станів і відповідального техніка."],"example":"Запис ноутбука не оновлювався 90 днів. Власник підтвердив, що ноутбук лежить у ремонті. Координатор не оголосив його очищеним після приховування; повернення на зв’язок стало окремим повторним переглядом.","implementation_methods":["Вести список кандидатів із фізичним відповідальним і рішенням за записом.","Зіставляти журнал приховування та повернення із погодженим списком, окремо від обліку майна."],"complexity":"medium","hours_min":14,"hours_max":28,"requirements":["Відомі ID, платформи та останній зв’язок; є власник фізичного парку.","Погоджено правила адміністративного приховування й повернення записів."],"limitations":["Приховування Intune не виконує wipe або retire та не видаляє запис Entra ID.","Відсутність зв’язку не доводить втрати чи безпечного очищення; деякі керовані сторонніми засобами пристрої не підтримують ці правила."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0254","reason":"Очищення пристрою перед передаванням перевіряє дані на обладнанні; приховування адміністративного запису цього не виконує."},{"type":"related","target_id":"AUT-0119","reason":"Фізичне вибуття активу має окремі документи; неактивний запис не доводить вибуття."}],"configurator_questions":[{"id":"stale-managed-device-record-review-assets","question":"Чи потрібно зіставляти неактивні записи з реєстром фізичного майна?","help_text":"Погодьте ключі серійного номера та обробку кількох записів одного пристрою.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Погодьте ключі серійного номера та обробку кількох записів одного пристрою."}]},{"id":"stale-managed-device-record-review-platforms","question":"Чи потрібні різні правила для кількох платформ?","help_text":"Укажіть строки й винятки; перекриття загального та окремого правила перевіряйте явно.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Укажіть строки й винятки; перекриття загального та окремого правила перевіряйте явно."}]}]},{"schema_version":1,"id":"AUT-0485","slug":"support-approved-file-elevation-followup","title":"Розгляд запиту на запуск конкретного файлу з підвищеними правами","summary":"Запит пов’язують із користувачем, пристроєм і файлом; адміністратор ухвалює рішення, а підтримка контролює його доставку та результат.","problem":"Працівник чекає запуску потрібного файлу, але адміністратор не бачить новий запит або погоджує лише за назвою. Відмову не повідомили, а дозвіл сприймають як постійні права адміністратора.","outcome":"Запит має перевірений файл, бізнес-підставу, рішення й строк дозволу; користувач знає результат, а погодження не підміняється загальними адміністративними правами.","category":"security-compliance","subcategory":"access","roles":["operations-manager","technician"],"industries":["cross-industry","it-saas"],"triggers":["Користувач подав підтримці запит на підвищений запуск файлу, який потребує погодження."],"workflow_steps":["Пов’язати запит із користувачем, пристроєм, відбитком чи іншими доступними метаданими файлу та бізнес-підставою.","Передати уповноваженому адміністратору відомості про видавця, файл і стан пристрою; змінений файл потребує нового розгляду.","Адміністратор погоджує або відхиляє конкретний запит із причиною; координатор контролює чергу необроблених запитів.","Після погодження перевірити доставку дозволу й доступний запуск на потрібному пристрої; після відмови повідомити користувача належним каналом.","Зафіксувати фактичний строк дозволу та результат; повторний запит після його завершення не продовжує попереднє рішення автоматично."],"requirements":["Доступний механізм підвищення для конкретного файлу й належні права адміністратора.","Погоджено правила перевірки видавця, метаданих та бізнес-підстави."],"limitations":["Дозвіл не робить користувача постійним адміністратором і не доводить безпечності файлу.","У документованому EPM дозвіл діє 24 години від погодження; довільний строк і дострокове скасування цього погодження не підтримані.","Доступи, ліцензії та підтримку конкретного середовища перевіряють перед впровадженням; години попередні."],"problems":["Працівник чекає запуску потрібного файлу, але адміністратор не бачить новий запит або погоджує лише за назвою. Відмову не повідомили, а дозвіл сприймають як постійні права адміністратора."],"synonyms":["погодження підвищеного запуску","EPM elevation request","адміністративний запуск файлу"],"search_queries":["як контролювати запит працівника на запуск файлу з підвищеними правами"],"sources":[{"type":"vendor_documentation","title":"Microsoft Intune: Support approved file elevations","url":"https://learn.microsoft.com/en-us/intune/epm/manage-support-approvals","checked_at":"2026-10-09","supports":"Описано запит із користувачем, пристроєм і файлом, scoped права адміністратора, причини рішення та 24-годинний дозвіл. Нові запити не сповіщають адміністратора автоматично; відмову користувачу повідомляють окремо."},{"type":"inferred_pattern","title":"Редакційна модель контролю пристрою","supports":"Маршрут задач, звірки, ескалація, приклад, конфігураційні питання й години — гіпотези для аудиту. Джерела Microsoft не підтверджують реалізацію PlanFix чи клієнтський кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"support-approved-file-elevation-followup-tracked","title":"Контроль із перевіркою стану пристрою","description":"Запит пов’язують із користувачем, пристроєм і файлом; адміністратор ухвалює рішення, а підтримка контролює його доставку та результат.","best_for":["Команда має керовані пристрої, авторитетне джерело станів і відповідального техніка."],"example":"Працівник запросив запуск утиліти. Координатор передав адміністратору файл і його видавця. Після погодження пристрій ще не отримав політику, тому звернення залишили відкритим до фактичної синхронізації й запуску.","implementation_methods":["Вести чергу запитів із конкретним файлом, підставою, рішенням та строком.","Звіряти погодження в EPM з доставкою й підтвердженням користувача без надання загальних прав адміністратора."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Доступний механізм підвищення для конкретного файлу й належні права адміністратора.","Погоджено правила перевірки видавця, метаданих та бізнес-підстави."],"limitations":["Дозвіл не робить користувача постійним адміністратором і не доводить безпечності файлу.","У документованому EPM дозвіл діє 24 години від погодження; довільний строк і дострокове скасування цього погодження не підтримані."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0146","reason":"Тимчасове призначення прав до ресурсу має інший об’єкт. Тут погоджується виконання конкретного файлу певним користувачем на пристрої."},{"type":"related","target_id":"AUT-0464","reason":"Аварійний адміністративний доступ призначений для іншої мети; погодження файлу не надає аварійного акаунта."}],"configurator_questions":[{"id":"support-approved-file-elevation-followup-metadata","question":"Чи потрібно автоматично отримувати метадані файлу й стан запиту?","help_text":"Перевірте доступний інтерфейс та область прав; не передавайте сам файл у відкритий контур.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Перевірте доступний інтерфейс та область прав; не передавайте сам файл у відкритий контур."}]},{"id":"support-approved-file-elevation-followup-routing","question":"Чи потрібні різні погоджувачі для груп пристроїв і типів файлів?","help_text":"Погодьте маршрути з урахуванням scoped прав адміністратора.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Погодьте маршрути з урахуванням scoped прав адміністратора."}]}]}];
